INSERT INTO public."transcription" (id,"name",code,"created_at","order",tags,"content","section","transcription_text") VALUES
	 ('aace2a02-f7d2-407c-945a-178ad1ef89aa','19. Serializable.mp3','SQL_ISOLATIONS','2026-04-10 12:13:22.227',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Serializable говорит нам о том, что все транзакции, которые выполняются, будут выполняться в сериализованном виде.", "offsets": {"to": 10820, "from": 0}, "timestamps": {"to": "00:00:10,820", "from": "00:00:00,000"}}, {"text": "Cada transaction is serialized and executed in form of sequential consistency.", "offsets": {"to": 16820, "from": 10820}, "timestamps": {"to": "00:00:16,820", "from": "00:00:10,820"}}, {"text": "То есть это то же самое, что похоже на memory module в разных языках программирования.", "offsets": {"to": 21820, "from": 16820}, "timestamps": {"to": "00:00:21,820", "from": "00:00:16,820"}}, {"text": "Sequential consistency, когда разные сущности будут выполняться друг за другом, но не параллельно.", "offsets": {"to": 29720, "from": 21820}, "timestamps": {"to": "00:00:29,720", "from": "00:00:21,820"}}, {"text": "И база данных решает и она убеждается, что все транзакции будут выполнены, их результат, их несколько,", "offsets": {"to": 41760, "from": 30380}, "timestamps": {"to": "00:00:41,760", "from": "00:00:30,380"}}, {"text": "но что их результат, их выполнение будет последовательней, sequential.", "offsets": {"to": 47220, "from": 41760}, "timestamps": {"to": "00:00:47,220", "from": "00:00:41,760"}}, {"text": "Если вдруг две транзакции пересекаются с одними и теми же данными каким-то образом,", "offsets": {"to": 54040, "from": 47220}, "timestamps": {"to": "00:00:54,040", "from": "00:00:47,220"}}, {"text": "граф у нас зацикливается или что-то в этом роде делается,", "offsets": {"to": 57880, "from": 54040}, "timestamps": {"to": "00:00:57,880", "from": "00:00:54,040"}}, {"text": "то одна из них будет роллбочина с ошибкой.", "offsets": {"to": 61720, "from": 58480}, "timestamps": {"to": "00:01:01,720", "from": "00:00:58,480"}}, {"text": "Ну, будет ошибка, и мы должны будем повторить ее.", "offsets": {"to": 64460, "from": 61720}, "timestamps": {"to": "00:01:04,460", "from": "00:01:01,720"}}, {"text": "Если они последовательные, то все хорошо.", "offsets": {"to": 67040, "from": 64460}, "timestamps": {"to": "00:01:07,040", "from": "00:01:04,460"}}, {"text": "И Serializable как раз пытается нам обеспечить это.", "offsets": {"to": 71860, "from": 67040}, "timestamps": {"to": "00:01:11,860", "from": "00:01:07,040"}}, {"text": "Как будто мы параллельность полностью убираем.", "offsets": {"to": 76200, "from": 71860}, "timestamps": {"to": "00:01:16,200", "from": "00:01:11,860"}}, {"text": "И все, что у нас происходит, это последовательная.", "offsets": {"to": 79460, "from": 76200}, "timestamps": {"to": "00:01:19,460", "from": "00:01:16,200"}}, {"text": "У нас больше нет потока в базе данных, как будто и наши транзакции одна за другой выполняются.", "offsets": {"to": 85020, "from": 79460}, "timestamps": {"to": "00:01:25,020", "from": "00:01:19,460"}}, {"text": "Если это не так, то та транзакция, которая конфликтует, будет с ошибкой возвращена программе.", "offsets": {"to": 92260, "from": 85020}, "timestamps": {"to": "00:01:32,260", "from": "00:01:25,020"}}, {"text": "Повторите, пожалуйста.", "offsets": {"to": 93300, "from": 92260}, "timestamps": {"to": "00:01:33,300", "from": "00:01:32,260"}}, {"text": "Она обеспечивает, я тут пишу, наименьший уровень concurrency,", "offsets": {"to": 99160, "from": 93300}, "timestamps": {"to": "00:01:39,160", "from": "00:01:33,300"}}, {"text": "но очень высокий data consistency.", "offsets": {"to": 103940, "from": 99160}, "timestamps": {"to": "00:01:43,940", "from": "00:01:39,160"}}, {"text": "То есть, у нас уже намного-намного лучше, очень много аномалий исключено, почти все исключены.", "offsets": {"to": 109940, "from": 104200}, "timestamps": {"to": "00:01:49,940", "from": "00:01:44,200"}}, {"text": "Но есть...", "offsets": {"to": 111360, "from": 109940}, "timestamps": {"to": "00:01:51,360", "from": "00:01:49,940"}}, {"text": "Я нашел, например, одну аномалию, которая не срабатывает здесь.", "offsets": {"to": 115640, "from": 111360}, "timestamps": {"to": "00:01:55,640", "from": "00:01:51,360"}}, {"text": "Serializable не ловит.", "offsets": {"to": 116980, "from": 115640}, "timestamps": {"to": "00:01:56,980", "from": "00:01:55,640"}}, {"text": "Поэтому часто, наверное, стоит все-таки лочки использовать...", "offsets": {"to": 123500, "from": 118880}, "timestamps": {"to": "00:02:03,500", "from": "00:01:58,880"}}, {"text": "Ну, короче, другие разные механизмы, которые могут помочь.", "offsets": {"to": 126120, "from": 123500}, "timestamps": {"to": "00:02:06,120", "from": "00:02:03,500"}}, {"text": "Не только уровень транзакции.", "offsets": {"to": 128780, "from": 126120}, "timestamps": {"to": "00:02:08,780", "from": "00:02:06,120"}}, {"text": "Вот.", "offsets": {"to": 130460, "from": 128780}, "timestamps": {"to": "00:02:10,460", "from": "00:02:08,780"}}, {"text": "То есть, повышение уровня транзакции, скорее всего, будет у вас самым последним действием.", "offsets": {"to": 134900, "from": 130460}, "timestamps": {"to": "00:02:14,900", "from": "00:02:10,460"}}, {"text": "Вот.", "offsets": {"to": 136440, "from": 134900}, "timestamps": {"to": "00:02:16,440", "from": "00:02:14,900"}}, {"text": "То есть, я говорю, что он данный уровень у разных базов данных реализуется,", "offsets": {"to": 143240, "from": 137520}, "timestamps": {"to": "00:02:23,240", "from": "00:02:17,520"}}, {"text": "может быть, достигнут, очевидно, с помощью либо pessimistic locking или optimistic locking.", "offsets": {"to": 151360, "from": 143240}, "timestamps": {"to": "00:02:31,360", "from": "00:02:23,240"}}, {"text": "Это два разных типа блокирования.", "offsets": {"to": 153680, "from": 151360}, "timestamps": {"to": "00:02:33,680", "from": "00:02:31,360"}}, {"text": "То есть, pessimistic, он полностью блокирует наши строки или таблицу или что-то в этом роде", "offsets": {"to": 158960, "from": 153680}, "timestamps": {"to": "00:02:38,960", "from": "00:02:33,680"}}, {"text": "и не дает другим транзакциям дальше идти.", "offsets": {"to": 162640, "from": 158960}, "timestamps": {"to": "00:02:42,640", "from": "00:02:38,960"}}, {"text": "Он все стопорит, не дает выполняться больше ничему.", "offsets": {"to": 166180, "from": 162640}, "timestamps": {"to": "00:02:46,180", "from": "00:02:42,640"}}, {"text": "Это как Mutex, короче.", "offsets": {"to": 168700, "from": 166600}, "timestamps": {"to": "00:02:48,700", "from": "00:02:46,600"}}, {"text": "Вот.", "offsets": {"to": 169820, "from": 168700}, "timestamps": {"to": "00:02:49,820", "from": "00:02:48,700"}}, {"text": "Такая же логика.", "offsets": {"to": 171800, "from": 169820}, "timestamps": {"to": "00:02:51,800", "from": "00:02:49,820"}}, {"text": "Вот.", "offsets": {"to": 173280, "from": 171800}, "timestamps": {"to": "00:02:53,280", "from": "00:02:51,800"}}, {"text": "А optimistic locking, он использует версии и другие штуки, механизмы,", "offsets": {"to": 179680, "from": 173280}, "timestamps": {"to": "00:02:59,680", "from": "00:02:53,280"}}, {"text": "которые говорят, что если у нас есть конфликт,", "offsets": {"to": 182040, "from": 179680}, "timestamps": {"to": "00:03:02,040", "from": "00:02:59,680"}}, {"text": "то текущая транзакция отсекается мгновенно,", "offsets": {"to": 184640, "from": 182040}, "timestamps": {"to": "00:03:04,640", "from": "00:03:02,040"}}, {"text": "и мы должны ее повторить.", "offsets": {"to": 185860, "from": 184640}, "timestamps": {"to": "00:03:05,860", "from": "00:03:04,640"}}, {"text": "Ну, типа, locking нет.", "offsets": {"to": 187220, "from": 185860}, "timestamps": {"to": "00:03:07,220", "from": "00:03:05,860"}}, {"text": "Вот.", "offsets": {"to": 188960, "from": 187220}, "timestamps": {"to": "00:03:08,960", "from": "00:03:07,220"}}, {"text": "Текущая транзакция...", "offsets": {"to": 189960, "from": 188960}, "timestamps": {"to": "00:03:09,960", "from": "00:03:08,960"}}, {"text": "Ну, я тут написал на duty reads,", "offsets": {"to": 191840, "from": 189960}, "timestamps": {"to": "00:03:11,840", "from": "00:03:09,960"}}, {"text": "non-repeatable read, phantom reads,", "offsets": {"to": 193840, "from": 191840}, "timestamps": {"to": "00:03:13,840", "from": "00:03:11,840"}}, {"text": "realization analysis, lost update,", "offsets": {"to": 196100, "from": 193840}, "timestamps": {"to": "00:03:16,100", "from": "00:03:13,840"}}, {"text": "она может все это зафиксить, нам убрать.", "offsets": {"to": 199160, "from": 196300}, "timestamps": {"to": "00:03:19,160", "from": "00:03:16,300"}}, {"text": "Но и concurrency уберет.", "offsets": {"to": 201660, "from": 199160}, "timestamps": {"to": "00:03:21,660", "from": "00:03:19,160"}}, {"text": "То есть, если у нас мега-производительная система,", "offsets": {"to": 206300, "from": 201660}, "timestamps": {"to": "00:03:26,300", "from": "00:03:21,660"}}, {"text": "нам нужна очень высокая производительность,", "offsets": {"to": 208840, "from": 206300}, "timestamps": {"to": "00:03:28,840", "from": "00:03:26,300"}}, {"text": "то, скорее всего, тут надо себе задать вопрос,", "offsets": {"to": 211220, "from": 208840}, "timestamps": {"to": "00:03:31,220", "from": "00:03:28,840"}}, {"text": "может быть, нам просто по-другому к этим данным доступ иметь,", "offsets": {"to": 214920, "from": 211220}, "timestamps": {"to": "00:03:34,920", "from": "00:03:31,220"}}, {"text": "перестроить, ну, логику, да, как-то немножко по-другому,", "offsets": {"to": 217960, "from": 214920}, "timestamps": {"to": "00:03:37,960", "from": "00:03:34,920"}}, {"text": "аж чтобы избежать вот этого.", "offsets": {"to": 219560, "from": 217960}, "timestamps": {"to": "00:03:39,560", "from": "00:03:37,960"}}, {"text": "Потому что у нас последовательность sequential будет на execution полностью.", "offsets": {"to": 225540, "from": 220080}, "timestamps": {"to": "00:03:45,540", "from": "00:03:40,080"}}, {"text": "и более, там еще другие могут быть проблемы,", "offsets": {"to": 229620, "from": 227440}, "timestamps": {"to": "00:03:49,620", "from": "00:03:47,440"}}, {"text": "о которых я вот чуть позже скажу.", "offsets": {"to": 231360, "from": 229620}, "timestamps": {"to": "00:03:51,360", "from": "00:03:49,620"}}, {"text": "То есть,", "offsets": {"to": 232020, "from": 231360}, "timestamps": {"to": "00:03:52,020", "from": "00:03:51,360"}}, {"text": "с одной стороны, вы можете сказать,", "offsets": {"to": 235260, "from": 232020}, "timestamps": {"to": "00:03:55,260", "from": "00:03:52,020"}}, {"text": "например,", "offsets": {"to": 235620, "from": 235260}, "timestamps": {"to": "00:03:55,620", "from": "00:03:55,260"}}, {"text": "serialize был,", "offsets": {"to": 236400, "from": 235620}, "timestamps": {"to": "00:03:56,400", "from": "00:03:55,620"}}, {"text": "я возьму Zayuz,", "offsets": {"to": 237300, "from": 236400}, "timestamps": {"to": "00:03:57,300", "from": "00:03:56,400"}}, {"text": "и вообще все классно будет.", "offsets": {"to": 238460, "from": 237300}, "timestamps": {"to": "00:03:58,460", "from": "00:03:57,300"}}, {"text": "но даже если не будет вот этих всех аномалий,", "offsets": {"to": 244040, "from": 238940}, "timestamps": {"to": "00:04:04,040", "from": "00:03:58,940"}}, {"text": "может случиться ситуация,", "offsets": {"to": 245580, "from": 244040}, "timestamps": {"to": "00:04:05,580", "from": "00:04:04,040"}}, {"text": "когда у вас производительность настолько сильно просядет,", "offsets": {"to": 248780, "from": 245580}, "timestamps": {"to": "00:04:08,780", "from": "00:04:05,580"}}, {"text": "даже хуже,", "offsets": {"to": 249680, "from": 248780}, "timestamps": {"to": "00:04:09,680", "from": "00:04:08,780"}}, {"text": "чем вы просто будете блокировать все.", "offsets": {"to": 251740, "from": 249680}, "timestamps": {"to": "00:04:11,740", "from": "00:04:09,680"}}, {"text": "Представляете, да?", "offsets": {"to": 253000, "from": 251740}, "timestamps": {"to": "00:04:13,000", "from": "00:04:11,740"}}, {"text": "То есть,", "offsets": {"to": 253380, "from": 253000}, "timestamps": {"to": "00:04:13,380", "from": "00:04:13,000"}}, {"text": "лочки будут быстрее работать,", "offsets": {"to": 255500, "from": 253380}, "timestamps": {"to": "00:04:15,500", "from": "00:04:13,380"}}, {"text": "если вы строки будете лочить просто.", "offsets": {"to": 257120, "from": 255500}, "timestamps": {"to": "00:04:17,120", "from": "00:04:15,500"}}, {"text": "А serialize будет просто уничтожать вашу систему.", "offsets": {"to": 261300, "from": 257120}, "timestamps": {"to": "00:04:21,300", "from": "00:04:17,120"}}, {"text": "Скажу позже,", "offsets": {"to": 262620, "from": 261800}, "timestamps": {"to": "00:04:22,620", "from": "00:04:21,800"}}, {"text": "почему.", "offsets": {"to": 262940, "from": 262620}, "timestamps": {"to": "00:04:22,940", "from": "00:04:22,620"}}, {"text": "Уничтожать.", "offsets": {"to": 266100, "from": 262940}, "timestamps": {"to": "00:04:26,100", "from": "00:04:22,940"}}, {"text": "Хорошее слово придумал.", "offsets": {"to": 268300, "from": 266100}, "timestamps": {"to": "00:04:28,300", "from": "00:04:26,100"}}, {"text": "Вот.", "offsets": {"to": 269500, "from": 268300}, "timestamps": {"to": "00:04:29,500", "from": "00:04:28,300"}}]}',NULL,NULL),
	 ('3cd6c8ff-64b9-4ef1-b161-019c56ff0145','20. Advantages and Disadvantages.mp3','SQL_ISOLATIONS','2026-04-10 12:13:31.711',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Advantages and disadvantages.", "offsets": {"to": 1400, "from": 0}, "timestamps": {"to": "00:00:01,400", "from": "00:00:00,000"}}, {"text": "То есть, ну, я уже сказал, да, уже много раз повторял,", "offsets": {"to": 4860, "from": 1400}, "timestamps": {"to": "00:00:04,860", "from": "00:00:01,400"}}, {"text": "что наименьший уровень транзакции обеспечивает максимальную конкуренсию и перформанс.", "offsets": {"to": 9560, "from": 4860}, "timestamps": {"to": "00:00:09,560", "from": "00:00:04,860"}}, {"text": "Но с риском потерять, да, взять какие-то, получить какие-то аномалии.", "offsets": {"to": 15620, "from": 9560}, "timestamps": {"to": "00:00:15,620", "from": "00:00:09,560"}}, {"text": "То есть, немножко ниже консистенции наших данных могут быть.", "offsets": {"to": 19100, "from": 15620}, "timestamps": {"to": "00:00:19,100", "from": "00:00:15,620"}}, {"text": "И поэтому, типа, нам, мы должны решить, что если наша программа,", "offsets": {"to": 23100, "from": 19100}, "timestamps": {"to": "00:00:23,100", "from": "00:00:19,100"}}, {"text": "наша бизнес-логика вполне допускает это, да,", "offsets": {"to": 25940, "from": 23100}, "timestamps": {"to": "00:00:25,940", "from": "00:00:23,100"}}, {"text": "что мы можем спокойно с этим жить, у нас нет какой-то фигни,", "offsets": {"to": 29280, "from": 25940}, "timestamps": {"to": "00:00:29,280", "from": "00:00:25,940"}}, {"text": "сложных, да, там каких-то непонятных мега-запросов, процедур и прочего,", "offsets": {"to": 33660, "from": 29520}, "timestamps": {"to": "00:00:33,660", "from": "00:00:29,520"}}, {"text": "которые никто не любит и усложняет вообще все,", "offsets": {"to": 36800, "from": 33660}, "timestamps": {"to": "00:00:36,800", "from": "00:00:33,660"}}, {"text": "то мы можем их использовать и, может быть, подтюнить их как-то лодчиками,", "offsets": {"to": 40660, "from": 36800}, "timestamps": {"to": "00:00:40,660", "from": "00:00:36,800"}}, {"text": "еще чем-то, и все окей.", "offsets": {"to": 42080, "from": 40660}, "timestamps": {"to": "00:00:42,080", "from": "00:00:40,660"}}, {"text": "Что, кстати, чаще всего и делается в большинстве компаний.", "offsets": {"to": 45460, "from": 42080}, "timestamps": {"to": "00:00:45,460", "from": "00:00:42,080"}}, {"text": "Вот.", "offsets": {"to": 47100, "from": 45460}, "timestamps": {"to": "00:00:47,100", "from": "00:00:45,460"}}, {"text": "И, ну, и они же могут, с помощью разных механизмов,", "offsets": {"to": 52060, "from": 47100}, "timestamps": {"to": "00:00:52,060", "from": "00:00:47,100"}}, {"text": "можно и аномалии многие убрать.", "offsets": {"to": 54000, "from": 52060}, "timestamps": {"to": "00:00:54,000", "from": "00:00:52,060"}}, {"text": "Вот.", "offsets": {"to": 55400, "from": 54000}, "timestamps": {"to": "00:00:55,400", "from": "00:00:54,000"}}, {"text": "Не только повышением уровня транзакции.", "offsets": {"to": 58420, "from": 55400}, "timestamps": {"to": "00:00:58,420", "from": "00:00:55,400"}}, {"text": "И дальше.", "offsets": {"to": 60000, "from": 59040}, "timestamps": {"to": "00:01:00,000", "from": "00:00:59,040"}}, {"text": "Более высокий уровень транзакции будет гарантировать нам", "offsets": {"to": 64120, "from": 60000}, "timestamps": {"to": "00:01:04,120", "from": "00:01:00,000"}}, {"text": "более меньшую конкуренция перформанс,", "offsets": {"to": 66060, "from": 64120}, "timestamps": {"to": "00:01:06,060", "from": "00:01:04,120"}}, {"text": "но более высокую консистенцию до этой консистенции.", "offsets": {"to": 70280, "from": 66060}, "timestamps": {"to": "00:01:10,280", "from": "00:01:06,060"}}, {"text": "Потому что мы будем убирать разные аномалии", "offsets": {"to": 73740, "from": 70280}, "timestamps": {"to": "00:01:13,740", "from": "00:01:10,280"}}, {"text": "и увеличивать либо локинг,", "offsets": {"to": 76420, "from": 73740}, "timestamps": {"to": "00:01:16,420", "from": "00:01:13,740"}}, {"text": "либо повторение, да, транзакции.", "offsets": {"to": 80660, "from": 76420}, "timestamps": {"to": "00:01:20,660", "from": "00:01:16,420"}}, {"text": "Будем повторять их постоянно.", "offsets": {"to": 81820, "from": 80660}, "timestamps": {"to": "00:01:21,820", "from": "00:01:20,660"}}, {"text": "Да.", "offsets": {"to": 82980, "from": 81820}, "timestamps": {"to": "00:01:22,980", "from": "00:01:21,820"}}]}',NULL,NULL),
	 ('31326d03-ce21-41f5-855d-9e38b76df4e5','21. How to choose.mp3','SQL_ISOLATIONS','2026-04-10 12:13:53.833',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Как нам выбирать правильный уровень транзакции?", "offsets": {"to": 5980, "from": 0}, "timestamps": {"to": "00:00:05,980", "from": "00:00:00,000"}}, {"text": "Непонятно, да?", "offsets": {"to": 6740, "from": 5980}, "timestamps": {"to": "00:00:06,740", "from": "00:00:05,980"}}, {"text": "Ну, уже понятно, я уже сказал.", "offsets": {"to": 8960, "from": 6740}, "timestamps": {"to": "00:00:08,960", "from": "00:00:06,740"}}, {"text": "И у меня вообще нет никакой этой изюминки.", "offsets": {"to": 12740, "from": 8960}, "timestamps": {"to": "00:00:12,740", "from": "00:00:08,960"}}, {"text": "Я всё сразу сказал.", "offsets": {"to": 13820, "from": 12740}, "timestamps": {"to": "00:00:13,820", "from": "00:00:12,740"}}, {"text": "Ну, короче, может, поэтому лайков так мало ставить.", "offsets": {"to": 18120, "from": 13820}, "timestamps": {"to": "00:00:18,120", "from": "00:00:13,820"}}, {"text": "Надо, типа, всё самое интересное, все ответы на потом сохранять,", "offsets": {"to": 21660, "from": 18120}, "timestamps": {"to": "00:00:21,660", "from": "00:00:18,120"}}, {"text": "чтобы не говорить ничего, чтобы сложно найти иглы,", "offsets": {"to": 26160, "from": 21660}, "timestamps": {"to": "00:00:26,160", "from": "00:00:21,660"}}, {"text": "чтобы слушать прям надо было всё.", "offsets": {"to": 27620, "from": 26160}, "timestamps": {"to": "00:00:27,620", "from": "00:00:26,160"}}, {"text": "Мне кажется, все так делают,", "offsets": {"to": 29600, "from": 27620}, "timestamps": {"to": "00:00:29,600", "from": "00:00:27,620"}}, {"text": "а я прям сразу всё выкладываю,", "offsets": {"to": 31000, "from": 29700}, "timestamps": {"to": "00:00:31,000", "from": "00:00:29,700"}}, {"text": "и никому не интересно, потому что всё сказал уже.", "offsets": {"to": 34360, "from": 31000}, "timestamps": {"to": "00:00:34,360", "from": "00:00:31,000"}}, {"text": "Ну, короче, суть в том, что read-committed у вас будет использоваться", "offsets": {"to": 38140, "from": 34360}, "timestamps": {"to": "00:00:38,140", "from": "00:00:34,360"}}, {"text": "в большинстве ваших приложений, в большинстве компаний,", "offsets": {"to": 40980, "from": 38140}, "timestamps": {"to": "00:00:40,980", "from": "00:00:38,140"}}, {"text": "куда вы будете устраиваться.", "offsets": {"to": 42420, "from": 40980}, "timestamps": {"to": "00:00:42,420", "from": "00:00:40,980"}}, {"text": "Почти у всех, кого я знаю, на работе используется read-committed.", "offsets": {"to": 47200, "from": 42420}, "timestamps": {"to": "00:00:47,200", "from": "00:00:42,420"}}, {"text": "Типа, я даже, блин, я вот тут делал опрос,", "offsets": {"to": 50680, "from": 47200}, "timestamps": {"to": "00:00:50,680", "from": "00:00:47,200"}}, {"text": "и ни у кого нет, короче, ничего больше.", "offsets": {"to": 52440, "from": 50680}, "timestamps": {"to": "00:00:52,440", "from": "00:00:50,680"}}, {"text": "Ну, типа, только read-committed.", "offsets": {"to": 53560, "from": 52440}, "timestamps": {"to": "00:00:53,560", "from": "00:00:52,440"}}, {"text": "То есть, там они используют разные везде, в разных компаниях.", "offsets": {"to": 57760, "from": 53560}, "timestamps": {"to": "00:00:57,760", "from": "00:00:53,560"}}, {"text": "Ну, используют похожие техники,", "offsets": {"to": 59120, "from": 57760}, "timestamps": {"to": "00:00:59,120", "from": "00:00:57,760"}}, {"text": "для избежания аномалий и избежания конкретного доступа к данным.", "offsets": {"to": 63820, "from": 59400}, "timestamps": {"to": "00:01:03,820", "from": "00:00:59,400"}}, {"text": "Да, shared data какой-то, если у нас есть,", "offsets": {"to": 65660, "from": 63820}, "timestamps": {"to": "00:01:05,660", "from": "00:01:03,820"}}, {"text": "critical data, critical shared data,", "offsets": {"to": 69200, "from": 65660}, "timestamps": {"to": "00:01:09,200", "from": "00:01:05,660"}}, {"text": "которые несколько потоков,", "offsets": {"to": 70480, "from": 69200}, "timestamps": {"to": "00:01:10,480", "from": "00:01:09,200"}}, {"text": "несколько транзакций оперируют,", "offsets": {"to": 72100, "from": 70480}, "timestamps": {"to": "00:01:12,100", "from": "00:01:10,480"}}, {"text": "читают, пишут оттуда,", "offsets": {"to": 73860, "from": 72100}, "timestamps": {"to": "00:01:13,860", "from": "00:01:12,100"}}, {"text": "то используются немножко другие механизмы специальные,", "offsets": {"to": 77040, "from": 73860}, "timestamps": {"to": "00:01:17,040", "from": "00:01:13,860"}}, {"text": "о которых мы потом поговорим,", "offsets": {"to": 78180, "from": 77040}, "timestamps": {"to": "00:01:18,180", "from": "00:01:17,040"}}, {"text": "потому что уже полтора часа почти, я думаю, никто уже не смотрит.", "offsets": {"to": 82860, "from": 78240}, "timestamps": {"to": "00:01:22,860", "from": "00:01:18,240"}}, {"text": "Я тут сам для себя уже.", "offsets": {"to": 84500, "from": 82860}, "timestamps": {"to": "00:01:24,500", "from": "00:01:22,860"}}, {"text": "Если кто-то смотрит, напишите в комментариях,", "offsets": {"to": 87580, "from": 84500}, "timestamps": {"to": "00:01:27,580", "from": "00:01:24,500"}}, {"text": "что вы дошли до сюда.", "offsets": {"to": 88620, "from": 87580}, "timestamps": {"to": "00:01:28,620", "from": "00:01:27,580"}}, {"text": "Вот.", "offsets": {"to": 90080, "from": 88620}, "timestamps": {"to": "00:01:30,080", "from": "00:01:28,620"}}, {"text": "Мне просто интересно.", "offsets": {"to": 91720, "from": 90080}, "timestamps": {"to": "00:01:31,720", "from": "00:01:30,080"}}, {"text": "Мне кажется, никто не доходит.", "offsets": {"to": 93800, "from": 91720}, "timestamps": {"to": "00:01:33,800", "from": "00:01:31,720"}}, {"text": "Вот.", "offsets": {"to": 94720, "from": 93800}, "timestamps": {"to": "00:01:34,720", "from": "00:01:33,800"}}, {"text": "Это даст нам максимальную,", "offsets": {"to": 96500, "from": 94920}, "timestamps": {"to": "00:01:36,500", "from": "00:01:34,920"}}, {"text": "ну, как, оптимальную производительность,", "offsets": {"to": 98880, "from": 96500}, "timestamps": {"to": "00:01:38,880", "from": "00:01:36,500"}}, {"text": "concurrency,", "offsets": {"to": 100100, "from": 98880}, "timestamps": {"to": "00:01:40,100", "from": "00:01:38,880"}}, {"text": "но немножко компроманс-консистенцию.", "offsets": {"to": 102760, "from": 100100}, "timestamps": {"to": "00:01:42,760", "from": "00:01:40,100"}}, {"text": "Repeatable read можно использовать,", "offsets": {"to": 105640, "from": 102760}, "timestamps": {"to": "00:01:45,640", "from": "00:01:42,760"}}, {"text": "если мы хотим все время читать одни и те же данные.", "offsets": {"to": 109680, "from": 105640}, "timestamps": {"to": "00:01:49,680", "from": "00:01:45,640"}}, {"text": "Мы хотим убрать repeatable read,", "offsets": {"to": 112900, "from": 109680}, "timestamps": {"to": "00:01:52,900", "from": "00:01:49,680"}}, {"text": "аномалия,", "offsets": {"to": 114260, "from": 112960}, "timestamps": {"to": "00:01:54,260", "from": "00:01:52,960"}}, {"text": "а вот.", "offsets": {"to": 115820, "from": 114260}, "timestamps": {"to": "00:01:55,820", "from": "00:01:54,260"}}, {"text": "И мы хотим убрать фантомы какие-то.", "offsets": {"to": 118760, "from": 115820}, "timestamps": {"to": "00:01:58,760", "from": "00:01:55,820"}}, {"text": "Ну, хотим читать одно и то же постоянно,", "offsets": {"to": 120580, "from": 118760}, "timestamps": {"to": "00:02:00,580", "from": "00:01:58,760"}}, {"text": "даже если это меняют параллельно.", "offsets": {"to": 121960, "from": 120580}, "timestamps": {"to": "00:02:01,960", "from": "00:02:00,580"}}, {"text": "То есть в Postgres оно будет так работать.", "offsets": {"to": 124760, "from": 121960}, "timestamps": {"to": "00:02:04,760", "from": "00:02:01,960"}}, {"text": "Оно будет использовать", "offsets": {"to": 126320, "from": 124760}, "timestamps": {"to": "00:02:06,320", "from": "00:02:04,760"}}, {"text": "multi-version control механизм,", "offsets": {"to": 127960, "from": 126320}, "timestamps": {"to": "00:02:07,960", "from": "00:02:06,320"}}, {"text": "специальный механизм лочек,", "offsets": {"to": 130440, "from": 127960}, "timestamps": {"to": "00:02:10,440", "from": "00:02:07,960"}}, {"text": "который, ну, не лочек,", "offsets": {"to": 132120, "from": 130440}, "timestamps": {"to": "00:02:12,120", "from": "00:02:10,440"}}, {"text": "а вершин, ну, как бы,", "offsets": {"to": 133260, "from": 132120}, "timestamps": {"to": "00:02:13,260", "from": "00:02:12,120"}}, {"text": "кратких лочек таких,", "offsets": {"to": 134820, "from": 133260}, "timestamps": {"to": "00:02:14,820", "from": "00:02:13,260"}}, {"text": "там, специальные лочки.", "offsets": {"to": 136000, "from": 134820}, "timestamps": {"to": "00:02:16,000", "from": "00:02:14,820"}}, {"text": "Вот.", "offsets": {"to": 136800, "from": 136000}, "timestamps": {"to": "00:02:16,800", "from": "00:02:16,000"}}, {"text": "И они, ну, будут,", "offsets": {"to": 140060, "from": 136800}, "timestamps": {"to": "00:02:20,060", "from": "00:02:16,800"}}, {"text": "не сильно будут нагружать,", "offsets": {"to": 141920, "from": 140060}, "timestamps": {"to": "00:02:21,920", "from": "00:02:20,060"}}, {"text": "ну, не мега.", "offsets": {"to": 143160, "from": 142000}, "timestamps": {"to": "00:02:23,160", "from": "00:02:22,000"}}, {"text": "Ну, если мега нагруженная система,", "offsets": {"to": 144860, "from": 143160}, "timestamps": {"to": "00:02:24,860", "from": "00:02:23,160"}}, {"text": "скорее всего, просадка будет.", "offsets": {"to": 146400, "from": 144860}, "timestamps": {"to": "00:02:26,400", "from": "00:02:24,860"}}, {"text": "Если не мега,", "offsets": {"to": 147980, "from": 146400}, "timestamps": {"to": "00:02:27,980", "from": "00:02:26,400"}}, {"text": "то, скорее всего,", "offsets": {"to": 148780, "from": 147980}, "timestamps": {"to": "00:02:28,780", "from": "00:02:27,980"}}, {"text": "вы можете не почувствовать.", "offsets": {"to": 150000, "from": 148780}, "timestamps": {"to": "00:02:30,000", "from": "00:02:28,780"}}, {"text": "Но стоит подумать прежде,", "offsets": {"to": 151820, "from": 150000}, "timestamps": {"to": "00:02:31,820", "from": "00:02:30,000"}}, {"text": "чем делать все равно.", "offsets": {"to": 152640, "from": 151820}, "timestamps": {"to": "00:02:32,640", "from": "00:02:31,820"}}, {"text": "Может быть, можно вот этим все-таки обойтись.", "offsets": {"to": 155240, "from": 152640}, "timestamps": {"to": "00:02:35,240", "from": "00:02:32,640"}}, {"text": "Ну, и serializable,", "offsets": {"to": 157440, "from": 155240}, "timestamps": {"to": "00:02:37,440", "from": "00:02:35,240"}}, {"text": "когда у вас есть сложные данные,", "offsets": {"to": 159040, "from": 157440}, "timestamps": {"to": "00:02:39,040", "from": "00:02:37,440"}}, {"text": "когда у вас есть вот эти вот случаи,", "offsets": {"to": 162280, "from": 159040}, "timestamps": {"to": "00:02:42,280", "from": "00:02:39,040"}}, {"text": "которые я описал, да,", "offsets": {"to": 163540, "from": 162280}, "timestamps": {"to": "00:02:43,540", "from": "00:02:42,280"}}, {"text": "вы их используете параллельно,", "offsets": {"to": 165120, "from": 163540}, "timestamps": {"to": "00:02:45,120", "from": "00:02:43,540"}}, {"text": "что-то читаете,", "offsets": {"to": 165820, "from": 165120}, "timestamps": {"to": "00:02:45,820", "from": "00:02:45,120"}}, {"text": "в разные места пишете,", "offsets": {"to": 167100, "from": 165820}, "timestamps": {"to": "00:02:47,100", "from": "00:02:45,820"}}, {"text": "циклические штуки делаете.", "offsets": {"to": 169600, "from": 167100}, "timestamps": {"to": "00:02:49,600", "from": "00:02:47,100"}}, {"text": "То есть вы сразу думаете,", "offsets": {"to": 171040, "from": 169600}, "timestamps": {"to": "00:02:51,040", "from": "00:02:49,600"}}, {"text": "блин, если у меня такая херня,", "offsets": {"to": 172760, "from": 171040}, "timestamps": {"to": "00:02:52,760", "from": "00:02:51,040"}}, {"text": "надо посмотреть в этом видосе,", "offsets": {"to": 174220, "from": 172760}, "timestamps": {"to": "00:02:54,220", "from": "00:02:52,760"}}, {"text": "он же говорил про это,", "offsets": {"to": 175500, "from": 174220}, "timestamps": {"to": "00:02:55,500", "from": "00:02:54,220"}}, {"text": "открыть, короче,", "offsets": {"to": 176900, "from": 175500}, "timestamps": {"to": "00:02:56,900", "from": "00:02:55,500"}}, {"text": "какой-то write-sq,", "offsets": {"to": 177960, "from": 176900}, "timestamps": {"to": "00:02:57,960", "from": "00:02:56,900"}}, {"text": "write-0,", "offsets": {"to": 178920, "from": 177960}, "timestamps": {"to": "00:02:58,920", "from": "00:02:57,960"}}, {"text": "one, two,", "offsets": {"to": 179480, "from": 178920}, "timestamps": {"to": "00:02:59,480", "from": "00:02:58,920"}}, {"text": "read-sq,", "offsets": {"to": 180040, "from": 179480}, "timestamps": {"to": "00:03:00,040", "from": "00:02:59,480"}}, {"text": "и посмотреть.", "offsets": {"to": 180680, "from": 180040}, "timestamps": {"to": "00:03:00,680", "from": "00:03:00,040"}}, {"text": "Возможно, это один из ваших случаев,", "offsets": {"to": 182620, "from": 180680}, "timestamps": {"to": "00:03:02,620", "from": "00:03:00,680"}}, {"text": "сложный какой-то.", "offsets": {"to": 183580, "from": 182620}, "timestamps": {"to": "00:03:03,580", "from": "00:03:02,620"}}, {"text": "И там вы уже не сможете просто так сделать.", "offsets": {"to": 186420, "from": 183580}, "timestamps": {"to": "00:03:06,420", "from": "00:03:03,580"}}, {"text": "Ну, либо реально,", "offsets": {"to": 187140, "from": 186420}, "timestamps": {"to": "00:03:07,140", "from": "00:03:06,420"}}, {"text": "как-то хитролочку поставить,", "offsets": {"to": 188740, "from": 187140}, "timestamps": {"to": "00:03:08,740", "from": "00:03:07,140"}}, {"text": "можно попробовать.", "offsets": {"to": 189500, "from": 188740}, "timestamps": {"to": "00:03:09,500", "from": "00:03:08,740"}}, {"text": "Либо просто попробовать сделать serializable.", "offsets": {"to": 191960, "from": 189500}, "timestamps": {"to": "00:03:11,960", "from": "00:03:09,500"}}, {"text": "и вы получите strict data integrity,", "offsets": {"to": 196400, "from": 192680}, "timestamps": {"to": "00:03:16,400", "from": "00:03:12,680"}}, {"text": "да,", "offsets": {"to": 196940, "from": 196400}, "timestamps": {"to": "00:03:16,940", "from": "00:03:16,400"}}, {"text": "consistent integrity,", "offsets": {"to": 198600, "from": 196940}, "timestamps": {"to": "00:03:18,600", "from": "00:03:16,940"}}, {"text": "то есть будет максимально ваших данных,", "offsets": {"to": 201240, "from": 198600}, "timestamps": {"to": "00:03:21,240", "from": "00:03:18,600"}}, {"text": "они будут безопасно с ними работать.", "offsets": {"to": 203200, "from": 201240}, "timestamps": {"to": "00:03:23,200", "from": "00:03:21,240"}}, {"text": "Но,", "offsets": {"to": 204140, "from": 203200}, "timestamps": {"to": "00:03:24,140", "from": "00:03:23,200"}}, {"text": "типа,", "offsets": {"to": 205000, "from": 204140}, "timestamps": {"to": "00:03:25,000", "from": "00:03:24,140"}}, {"text": "проблемы с перформансом могут быть", "offsets": {"to": 207480, "from": 205000}, "timestamps": {"to": "00:03:27,480", "from": "00:03:25,000"}}, {"text": "не мега большие,", "offsets": {"to": 208660, "from": 207480}, "timestamps": {"to": "00:03:28,660", "from": "00:03:27,480"}}, {"text": "но там на 30%,", "offsets": {"to": 210060, "from": 208660}, "timestamps": {"to": "00:03:30,060", "from": "00:03:28,660"}}, {"text": "что ли,", "offsets": {"to": 210360, "from": 210060}, "timestamps": {"to": "00:03:30,360", "from": "00:03:30,060"}}, {"text": "я читал,", "offsets": {"to": 210780, "from": 210360}, "timestamps": {"to": "00:03:30,780", "from": "00:03:30,360"}}, {"text": "может просесть даже.", "offsets": {"to": 212680, "from": 210780}, "timestamps": {"to": "00:03:32,680", "from": "00:03:30,780"}}, {"text": "Вот.", "offsets": {"to": 214500, "from": 212680}, "timestamps": {"to": "00:03:34,500", "from": "00:03:32,680"}}, {"text": "И главный совет,", "offsets": {"to": 215640, "from": 214880}, "timestamps": {"to": "00:03:35,640", "from": "00:03:34,880"}}, {"text": "который обычно говорят,", "offsets": {"to": 217960, "from": 215640}, "timestamps": {"to": "00:03:37,960", "from": "00:03:35,640"}}, {"text": "это то,", "offsets": {"to": 218400, "from": 217960}, "timestamps": {"to": "00:03:38,400", "from": "00:03:37,960"}}, {"text": "что уровень изоляции", "offsets": {"to": 219620, "from": 218400}, "timestamps": {"to": "00:03:39,620", "from": "00:03:38,400"}}, {"text": "должен быть выбран", "offsets": {"to": 220400, "from": 219620}, "timestamps": {"to": "00:03:40,400", "from": "00:03:39,620"}}, {"text": "не на основе перформанса,", "offsets": {"to": 222740, "from": 220400}, "timestamps": {"to": "00:03:42,740", "from": "00:03:40,400"}}, {"text": "да,", "offsets": {"to": 222880, "from": 222740}, "timestamps": {"to": "00:03:42,880", "from": "00:03:42,740"}}, {"text": "насколько вот быстро-быстро хочу,", "offsets": {"to": 224260, "from": 222880}, "timestamps": {"to": "00:03:44,260", "from": "00:03:42,880"}}, {"text": "а именно на задаче.", "offsets": {"to": 226280, "from": 224260}, "timestamps": {"to": "00:03:46,280", "from": "00:03:44,260"}}, {"text": "То есть,", "offsets": {"to": 226740, "from": 226280}, "timestamps": {"to": "00:03:46,740", "from": "00:03:46,280"}}, {"text": "если вы понимаете,", "offsets": {"to": 227420, "from": 226740}, "timestamps": {"to": "00:03:47,420", "from": "00:03:46,740"}}, {"text": "что у вас какая-то задача,", "offsets": {"to": 228440, "from": 227420}, "timestamps": {"to": "00:03:48,440", "from": "00:03:47,420"}}, {"text": "которая вот только вот это может использовать,", "offsets": {"to": 230240, "from": 228440}, "timestamps": {"to": "00:03:50,240", "from": "00:03:48,440"}}, {"text": "ну, реально,", "offsets": {"to": 230780, "from": 230240}, "timestamps": {"to": "00:03:50,780", "from": "00:03:50,240"}}, {"text": "вы никакие аномалии", "offsets": {"to": 232020, "from": 230780}, "timestamps": {"to": "00:03:52,020", "from": "00:03:50,780"}}, {"text": "не толерантны,", "offsets": {"to": 233320, "from": 232020}, "timestamps": {"to": "00:03:53,320", "from": "00:03:52,020"}}, {"text": "ни к одной аномалии вообще,", "offsets": {"to": 234740, "from": 233320}, "timestamps": {"to": "00:03:54,740", "from": "00:03:53,320"}}, {"text": "там у вас какая-то жопа,", "offsets": {"to": 236020, "from": 234740}, "timestamps": {"to": "00:03:56,020", "from": "00:03:54,740"}}, {"text": "тогда,", "offsets": {"to": 236920, "from": 236020}, "timestamps": {"to": "00:03:56,920", "from": "00:03:56,020"}}, {"text": "скорее всего,", "offsets": {"to": 237520, "from": 236920}, "timestamps": {"to": "00:03:57,520", "from": "00:03:56,920"}}, {"text": "лучше не изобретать велосибет", "offsets": {"to": 240480, "from": 237520}, "timestamps": {"to": "00:04:00,480", "from": "00:03:57,520"}}, {"text": "какой-то,", "offsets": {"to": 240860, "from": 240480}, "timestamps": {"to": "00:04:00,860", "from": "00:04:00,480"}}, {"text": "какие-то сложные локи,", "offsets": {"to": 242340, "from": 240860}, "timestamps": {"to": "00:04:02,340", "from": "00:04:00,860"}}, {"text": "с которыми потом никто не разберётся", "offsets": {"to": 244340, "from": 242340}, "timestamps": {"to": "00:04:04,340", "from": "00:04:02,340"}}, {"text": "и там будет куча косяков потом.", "offsets": {"to": 247040, "from": 244340}, "timestamps": {"to": "00:04:07,040", "from": "00:04:04,340"}}, {"text": "Ну, типа,", "offsets": {"to": 247380, "from": 247040}, "timestamps": {"to": "00:04:07,380", "from": "00:04:07,040"}}, {"text": "очень сложно,", "offsets": {"to": 248600, "from": 247380}, "timestamps": {"to": "00:04:08,600", "from": "00:04:07,380"}}, {"text": "очень легко сделать ошибку.", "offsets": {"to": 249920, "from": 248600}, "timestamps": {"to": "00:04:09,920", "from": "00:04:08,600"}}, {"text": "Может быть,", "offsets": {"to": 250580, "from": 249920}, "timestamps": {"to": "00:04:10,580", "from": "00:04:09,920"}}, {"text": "реально проще сделать", "offsets": {"to": 251500, "from": 250580}, "timestamps": {"to": "00:04:11,500", "from": "00:04:10,580"}}, {"text": "с реалайзбл", "offsets": {"to": 252240, "from": 251500}, "timestamps": {"to": "00:04:12,240", "from": "00:04:11,500"}}, {"text": "или репитабл.", "offsets": {"to": 253040, "from": 252240}, "timestamps": {"to": "00:04:13,040", "from": "00:04:12,240"}}, {"text": "Ну,", "offsets": {"to": 254660, "from": 253040}, "timestamps": {"to": "00:04:14,660", "from": "00:04:13,040"}}, {"text": "а в остальных случаях,", "offsets": {"to": 255460, "from": 254660}, "timestamps": {"to": "00:04:15,460", "from": "00:04:14,660"}}, {"text": "скорее всего,", "offsets": {"to": 255900, "from": 255460}, "timestamps": {"to": "00:04:15,900", "from": "00:04:15,460"}}, {"text": "всё довольно будет быстро работать", "offsets": {"to": 257340, "from": 255900}, "timestamps": {"to": "00:04:17,340", "from": "00:04:15,900"}}, {"text": "и с редкометод.", "offsets": {"to": 258440, "from": 257340}, "timestamps": {"to": "00:04:18,440", "from": "00:04:17,340"}}]}',NULL,NULL),
	 ('3be5e26b-47e8-421e-873e-5b2b08757076','22. Nuances with Read Committed.mp3','SQL_ISOLATIONS','2026-04-10 12:14:04.953',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Так, нюансы с read committed. Нюансы, которые мы имеем с read committed, значит. То есть наши данные, которые мы читаем, вообще с самую операцию read committed мы можем немножко сравнить с atomic variables, да, multitrading application, то есть atomic переменными.", "offsets": {"to": 21960, "from": 0}, "timestamps": {"to": "00:00:21,960", "from": "00:00:00,000"}}, {"text": "То есть мы читаем какой-то текущий snapshot наших данных, который был зафиксирован какими-то другими тредами. Только текущий зафиксированный. Он не будет читать какое-то промежуточное интермедиат состояние. Только закомиченные данные.", "offsets": {"to": 38900, "from": 21960}, "timestamps": {"to": "00:00:38,900", "from": "00:00:21,960"}}, {"text": "Эти данные могут после чтения как-то поменяться, измениться, удалиться. Мы об этом не знаем. Мы текущие, snapshot process читали. Что там с ними дальше происходит, мы уже как бы не знаем.", "offsets": {"to": 49640, "from": 39340}, "timestamps": {"to": "00:00:49,640", "from": "00:00:39,340"}}, {"text": "Если наша система гарантирует, что никто больше туда не лезет, тогда нам окей. Может, даже лодочки не нужны. Если там, наверное, будет какая-то штука, когда много потоков к ним лезут, тогда, возможно, уже будет проблема и надо стоять лодочки или версии вводить.", "offsets": {"to": 66600, "from": 49640}, "timestamps": {"to": "00:01:06,600", "from": "00:00:49,640"}}, {"text": "Или состояние какие-то специальные вводить, да. Если состояние плохое, например, какое-то, то мы не работаем с этими данными, потому что кто-то уже с ними работает.", "offsets": {"to": 76840, "from": 66600}, "timestamps": {"to": "00:01:16,840", "from": "00:01:06,600"}}, {"text": "И что мы еще имеем, это то, что...", "offsets": {"to": 82680, "from": 78640}, "timestamps": {"to": "00:01:22,680", "from": "00:01:18,640"}}, {"text": "Ну да, что то, что мы считали, мы читаем какие-то данные, и на основе этого чтения мы будем строить всю нашу бизнес-логику в нашей программе.", "offsets": {"to": 93720, "from": 82680}, "timestamps": {"to": "00:01:33,720", "from": "00:01:22,680"}}, {"text": "То есть мы ее выстраиваем, мы как-то...", "offsets": {"to": 96460, "from": 93720}, "timestamps": {"to": "00:01:36,460", "from": "00:01:33,720"}}, {"text": "Ну, на основе этих данных.", "offsets": {"to": 99500, "from": 96460}, "timestamps": {"to": "00:01:39,500", "from": "00:01:36,460"}}, {"text": "Они могут либо поменяться, либо еще что-то, мы должны это учитывать, либо гарантировать, что они не меняются.", "offsets": {"to": 104900, "from": 99500}, "timestamps": {"to": "00:01:44,900", "from": "00:01:39,500"}}, {"text": "То есть, read committed – это snapshot.", "offsets": {"to": 108060, "from": 104900}, "timestamps": {"to": "00:01:48,060", "from": "00:01:44,900"}}, {"text": "Продолжение следует.", "offsets": {"to": 110000, "from": 108640}, "timestamps": {"to": "00:01:50,000", "from": "00:01:48,640"}}]}',NULL,NULL),
	 ('c84634a8-a5cd-4730-9ae0-e78c9a3ea01b','23. Nuances with Serializable.mp3','SQL_ISOLATIONS','2026-04-10 12:14:59.877',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Сериалайзабл.", "offsets": {"to": 640, "from": 0}, "timestamps": {"to": "00:00:00,640", "from": "00:00:00,000"}}, {"text": "Сериалайзабл уже больше нюансов.", "offsets": {"to": 4680, "from": 640}, "timestamps": {"to": "00:00:04,680", "from": "00:00:00,640"}}, {"text": "Я тут выписывал разных штук.", "offsets": {"to": 6880, "from": 4680}, "timestamps": {"to": "00:00:06,880", "from": "00:00:04,680"}}, {"text": "Очень мелко, я знаю.", "offsets": {"to": 8060, "from": 6880}, "timestamps": {"to": "00:00:08,060", "from": "00:00:06,880"}}, {"text": "Я попробую просто словами проговорить.", "offsets": {"to": 9840, "from": 8060}, "timestamps": {"to": "00:00:09,840", "from": "00:00:08,060"}}, {"text": "Луп уберите.", "offsets": {"to": 10980, "from": 9840}, "timestamps": {"to": "00:00:10,980", "from": "00:00:09,840"}}, {"text": "Оно просто не владит.", "offsets": {"to": 13740, "from": 10980}, "timestamps": {"to": "00:00:13,740", "from": "00:00:10,980"}}, {"text": "Я хотел, короче, туда сделать побольше,", "offsets": {"to": 16940, "from": 13740}, "timestamps": {"to": "00:00:16,940", "from": "00:00:13,740"}}, {"text": "но мне кажется, неудобно будет это всё листать.", "offsets": {"to": 19140, "from": 16940}, "timestamps": {"to": "00:00:19,140", "from": "00:00:16,940"}}, {"text": "Я хотел, чтобы на одном страничке всё уместилось.", "offsets": {"to": 22280, "from": 19140}, "timestamps": {"to": "00:00:22,280", "from": "00:00:19,140"}}, {"text": "Не очень удобно листать.", "offsets": {"to": 24080, "from": 22280}, "timestamps": {"to": "00:00:24,080", "from": "00:00:22,280"}}, {"text": "Короче, в итоге меньше шрифт просто сделал.", "offsets": {"to": 26060, "from": 24080}, "timestamps": {"to": "00:00:26,060", "from": "00:00:24,080"}}, {"text": "Мне видно, а вам, наверное, увеличить надо или слушать просто.", "offsets": {"to": 28500, "from": 26060}, "timestamps": {"to": "00:00:28,500", "from": "00:00:26,060"}}, {"text": "Короче, все в том, что сериалайзабл в подгрессе", "offsets": {"to": 32080, "from": 29200}, "timestamps": {"to": "00:00:32,080", "from": "00:00:29,200"}}, {"text": "имплементировано как SSI, можете загуглить.", "offsets": {"to": 35620, "from": 32080}, "timestamps": {"to": "00:00:35,620", "from": "00:00:32,080"}}, {"text": "Это сериалайзабл снапшот айзолейшн.", "offsets": {"to": 38560, "from": 35620}, "timestamps": {"to": "00:00:38,560", "from": "00:00:35,620"}}, {"text": "То есть у нас в репетаблориде было просто снапшот айзолейшн.", "offsets": {"to": 42500, "from": 38560}, "timestamps": {"to": "00:00:42,500", "from": "00:00:38,560"}}, {"text": "На основе локов, вот этих version control локов специальных.", "offsets": {"to": 46180, "from": 42500}, "timestamps": {"to": "00:00:46,180", "from": "00:00:42,500"}}, {"text": "Это называется pessimistic locking.", "offsets": {"to": 48220, "from": 46180}, "timestamps": {"to": "00:00:48,220", "from": "00:00:46,180"}}, {"text": "Это она использует более современные сложные техники", "offsets": {"to": 53200, "from": 48220}, "timestamps": {"to": "00:00:53,200", "from": "00:00:48,220"}}, {"text": "на основе построения графов, зависимости и так далее,", "offsets": {"to": 55880, "from": 53200}, "timestamps": {"to": "00:00:55,880", "from": "00:00:53,200"}}, {"text": "чтобы понять, что разные транзакции", "offsets": {"to": 58400, "from": 55880}, "timestamps": {"to": "00:00:58,400", "from": "00:00:55,880"}}, {"text": "транзакции используют, как-то зависят друг от друга,", "offsets": {"to": 60740, "from": 58400}, "timestamps": {"to": "00:01:00,740", "from": "00:00:58,400"}}, {"text": "пересекаются.", "offsets": {"to": 61600, "from": 60740}, "timestamps": {"to": "00:01:01,600", "from": "00:01:00,740"}}, {"text": "Вот.", "offsets": {"to": 63500, "from": 61600}, "timestamps": {"to": "00:01:03,500", "from": "00:01:01,600"}}, {"text": "Дальше.", "offsets": {"to": 64920, "from": 63500}, "timestamps": {"to": "00:01:04,920", "from": "00:01:03,500"}}, {"text": "Да.", "offsets": {"to": 68280, "from": 64920}, "timestamps": {"to": "00:01:08,280", "from": "00:01:04,920"}}, {"text": "Я читал research, исследования, которые показывают в 2012 году.", "offsets": {"to": 74700, "from": 68280}, "timestamps": {"to": "00:01:14,700", "from": "00:01:08,280"}}, {"text": "Можете попробовать загуглить.", "offsets": {"to": 76080, "from": 74700}, "timestamps": {"to": "00:01:16,080", "from": "00:01:14,700"}}, {"text": "Может, что-то тоже интересное там найдёте.", "offsets": {"to": 79540, "from": 76080}, "timestamps": {"to": "00:01:19,540", "from": "00:01:16,080"}}, {"text": "Которые показывают, что в подгрессе SSI может быть", "offsets": {"to": 84000, "from": 79540}, "timestamps": {"to": "00:01:24,000", "from": "00:01:19,540"}}, {"text": "по производительности, особенно по операциям чтения.", "offsets": {"to": 86860, "from": 84000}, "timestamps": {"to": "00:01:26,860", "from": "00:01:24,000"}}, {"text": "Если у вас их очень много, интенсивный, read-intensive workloads,", "offsets": {"to": 90500, "from": 86860}, "timestamps": {"to": "00:01:30,500", "from": "00:01:26,860"}}, {"text": "он будет быстрее или быстрее точно работать, чем two-phase locking.", "offsets": {"to": 97060, "from": 90500}, "timestamps": {"to": "00:01:37,060", "from": "00:01:30,500"}}, {"text": "Двухшаговый, двухфазовый locking.", "offsets": {"to": 101460, "from": 97060}, "timestamps": {"to": "00:01:41,460", "from": "00:01:37,060"}}, {"text": "Который, например, раньше использовался в MySQL и так далее.", "offsets": {"to": 106260, "from": 102460}, "timestamps": {"to": "00:01:46,260", "from": "00:01:42,460"}}, {"text": "Он будет быстрее работать, причём там значительно.", "offsets": {"to": 110380, "from": 106260}, "timestamps": {"to": "00:01:50,380", "from": "00:01:46,260"}}, {"text": "И он может работать примерно даже на том же уровне, что и snapshot", "offsets": {"to": 115540, "from": 110380}, "timestamps": {"to": "00:01:55,540", "from": "00:01:50,380"}}, {"text": "изоляции, то есть на том же уровне, что и repeatable read, уровень изоляции.", "offsets": {"to": 124520, "from": 115540}, "timestamps": {"to": "00:02:04,520", "from": "00:01:55,540"}}, {"text": "То есть он плюс-минус где-то вот с repeatable read будет стоять.", "offsets": {"to": 128980, "from": 124520}, "timestamps": {"to": "00:02:08,980", "from": "00:02:04,520"}}, {"text": "То есть не так, что вы serialize был включили, у вас вообще там всё упало.", "offsets": {"to": 132400, "from": 128980}, "timestamps": {"to": "00:02:12,400", "from": "00:02:08,980"}}, {"text": "Типа на repeatable read было более-менее, а на serialize вообще всё плохо стало.", "offsets": {"to": 136920, "from": 132400}, "timestamps": {"to": "00:02:16,920", "from": "00:02:12,400"}}, {"text": "Нет, они будут плюс-минус, чуть похуже может будут.", "offsets": {"to": 139480, "from": 137000}, "timestamps": {"to": "00:02:19,480", "from": "00:02:17,000"}}, {"text": "Вот.", "offsets": {"to": 141080, "from": 139480}, "timestamps": {"to": "00:02:21,080", "from": "00:02:19,480"}}, {"text": "Там графики есть, я их вроде бы там сейчас покажу, которые я оттуда дёрнул из этого исследования.", "offsets": {"to": 148060, "from": 141080}, "timestamps": {"to": "00:02:28,060", "from": "00:02:21,080"}}, {"text": "А что я сейчас прямо покажу?", "offsets": {"to": 151340, "from": 148060}, "timestamps": {"to": "00:02:31,340", "from": "00:02:28,060"}}, {"text": "А, вот.", "offsets": {"to": 153260, "from": 151340}, "timestamps": {"to": "00:02:33,260", "from": "00:02:31,340"}}, {"text": "То есть вот мы видим, что двухфазовый вот этот locking, two-phase locking,", "offsets": {"to": 159180, "from": 153260}, "timestamps": {"to": "00:02:39,180", "from": "00:02:33,260"}}, {"text": "она прямо начинает проседать.", "offsets": {"to": 162000, "from": 159180}, "timestamps": {"to": "00:02:42,000", "from": "00:02:39,180"}}, {"text": "Тут, насколько я помню, memory configuration был, а здесь disk-bound configuration.", "offsets": {"to": 167540, "from": 162000}, "timestamps": {"to": "00:02:47,540", "from": "00:02:42,000"}}, {"text": "То есть это они делали, скажем так, веб-приложения, которые принимают разные запросы,", "offsets": {"to": 174660, "from": 167540}, "timestamps": {"to": "00:02:54,660", "from": "00:02:47,540"}}, {"text": "обрабатывают их и инициируют разные транзакции, да, там, и разные механизмы локов там и так далее.", "offsets": {"to": 181680, "from": 174660}, "timestamps": {"to": "00:03:01,680", "from": "00:02:54,660"}}, {"text": "То есть обычный SI у нас, да, он у нас что?", "offsets": {"to": 188600, "from": 182340}, "timestamps": {"to": "00:03:08,600", "from": "00:03:02,340"}}, {"text": "Он у нас, вот, он зелёненький идёт.", "offsets": {"to": 193260, "from": 188600}, "timestamps": {"to": "00:03:13,260", "from": "00:03:08,600"}}, {"text": "Наш SSI, который в serialize был, да, он уже идёт, ну, рядышком там почти идёт, ну, как бы с ним, да.", "offsets": {"to": 200820, "from": 193260}, "timestamps": {"to": "00:03:20,820", "from": "00:03:13,260"}}, {"text": "Two-phase locking там в MySQL, ну, вообще там, у него производительность просто падает здесь.", "offsets": {"to": 206560, "from": 201880}, "timestamps": {"to": "00:03:26,560", "from": "00:03:21,880"}}, {"text": "В disk-bound у них, вот они другой какой-то пример там делали, у них они, вот, плюс, ну, как одно и тоже почти шло, да, плюс-минус.", "offsets": {"to": 216300, "from": 206560}, "timestamps": {"to": "00:03:36,300", "from": "00:03:26,560"}}, {"text": "А two-phase locking опять просел.", "offsets": {"to": 218640, "from": 216300}, "timestamps": {"to": "00:03:38,640", "from": "00:03:36,300"}}, {"text": "Вот такая, короче, штука.", "offsets": {"to": 222020, "from": 220420}, "timestamps": {"to": "00:03:42,020", "from": "00:03:40,420"}}, {"text": "Что ещё у нас тут есть?", "offsets": {"to": 225240, "from": 222020}, "timestamps": {"to": "00:03:45,240", "from": "00:03:42,020"}}, {"text": "Да, если у нас high-contention workloads, я написал, вот, третье, видите, написал high-contention workloads,", "offsets": {"to": 235540, "from": 225240}, "timestamps": {"to": "00:03:55,540", "from": "00:03:45,240"}}, {"text": "то мы, скорее всего, more likely, это experience, то есть почувствуем уменьшенную производительность и пропускную способность и latency,", "offsets": {"to": 244660, "from": 235540}, "timestamps": {"to": "00:04:04,660", "from": "00:03:55,540"}}, {"text": "потому что все наши транзакции будут фейлиться, и мы должны будем их перезапускать постоянно.", "offsets": {"to": 252100, "from": 244660}, "timestamps": {"to": "00:04:12,100", "from": "00:04:04,660"}}, {"text": "High-contention workloads – это те workloads, когда вот этот вот,", "offsets": {"to": 256680, "from": 252100}, "timestamps": {"to": "00:04:16,680", "from": "00:04:12,100"}}, {"text": "когда у вас огромное количество параллельных потоков транзакций лезет к одним и тем же данным.", "offsets": {"to": 265400, "from": 256680}, "timestamps": {"to": "00:04:25,400", "from": "00:04:16,680"}}, {"text": "То есть у вас есть разделяемый shared resource, и множество потоков в него долбят постоянно.", "offsets": {"to": 271120, "from": 265400}, "timestamps": {"to": "00:04:31,120", "from": "00:04:25,400"}}, {"text": "И получается, что один из них пройдёт, все остальные, миллион потоков, например, ну, грубо говоря, они зафейлятся.", "offsets": {"to": 281740, "from": 271700}, "timestamps": {"to": "00:04:41,740", "from": "00:04:31,700"}}, {"text": "И нам в следующей итерации надо 990 вот этих 9 зафейлиных повторить.", "offsets": {"to": 288160, "from": 281740}, "timestamps": {"to": "00:04:48,160", "from": "00:04:41,740"}}, {"text": "То есть вы представляете, что происходит?", "offsets": {"to": 291000, "from": 288160}, "timestamps": {"to": "00:04:51,000", "from": "00:04:48,160"}}, {"text": "То есть там может происходить реальный шторм повторений, шторм транзакций,", "offsets": {"to": 297760, "from": 291200}, "timestamps": {"to": "00:04:57,760", "from": "00:04:51,200"}}, {"text": "когда у вас по сети начинают гоняться вот эти транзакции, создаваться,", "offsets": {"to": 304300, "from": 297760}, "timestamps": {"to": "00:05:04,300", "from": "00:04:57,760"}}, {"text": "это всё фигачится в базу, фигачится, то есть кусками сразу много,", "offsets": {"to": 308520, "from": 304300}, "timestamps": {"to": "00:05:08,520", "from": "00:05:04,300"}}, {"text": "а отказало почти всё, опять заново, заново, заново, заново.", "offsets": {"to": 312740, "from": 308520}, "timestamps": {"to": "00:05:12,740", "from": "00:05:08,520"}}, {"text": "То есть и это всё, по сути, ну, просто убьёт базу данных, скорее всего, и сеть вашу, и так далее.", "offsets": {"to": 322640, "from": 312740}, "timestamps": {"to": "00:05:22,640", "from": "00:05:12,740"}}, {"text": "То есть будет работать, ну, точно будет работать дольше, чем просто заулочить.", "offsets": {"to": 328240, "from": 322640}, "timestamps": {"to": "00:05:28,240", "from": "00:05:22,640"}}, {"text": "Об этом мы тоже там потом поговорим в следующем видео.", "offsets": {"to": 330720, "from": 328240}, "timestamps": {"to": "00:05:30,720", "from": "00:05:28,240"}}, {"text": "Дальше.", "offsets": {"to": 334520, "from": 332020}, "timestamps": {"to": "00:05:34,520", "from": "00:05:32,020"}}, {"text": "Подпис использует специальный предикат локс, алгоритм,", "offsets": {"to": 339140, "from": 334520}, "timestamps": {"to": "00:05:39,140", "from": "00:05:34,520"}}, {"text": "который может детектить разные ошибки синхронизации, разные аномалии.", "offsets": {"to": 345880, "from": 339140}, "timestamps": {"to": "00:05:45,880", "from": "00:05:39,140"}}, {"text": "И он не вызывает особо никаких блоков, только там в каких-то крайних некоторых случаях.", "offsets": {"to": 352680, "from": 345880}, "timestamps": {"to": "00:05:52,680", "from": "00:05:45,880"}}, {"text": "И чаще всего он не будет приводить к дедлокам, поэтому.", "offsets": {"to": 355580, "from": 352680}, "timestamps": {"to": "00:05:55,580", "from": "00:05:52,680"}}, {"text": "То есть данный алгоритм, он понижает вероятность какого-то дедлока.", "offsets": {"to": 361780, "from": 355580}, "timestamps": {"to": "00:06:01,780", "from": "00:05:55,580"}}, {"text": "Вот, SSI, он работает только на Serializable.", "offsets": {"to": 367520, "from": 362020}, "timestamps": {"to": "00:06:07,520", "from": "00:06:02,020"}}, {"text": "SSI только на...", "offsets": {"to": 369960, "from": 367520}, "timestamps": {"to": "00:06:09,960", "from": "00:06:07,520"}}, {"text": "Где я там?", "offsets": {"to": 370800, "from": 369960}, "timestamps": {"to": "00:06:10,800", "from": "00:06:09,960"}}, {"text": "Где я?", "offsets": {"to": 375340, "from": 370800}, "timestamps": {"to": "00:06:15,340", "from": "00:06:10,800"}}, {"text": "Где я?", "offsets": {"to": 376700, "from": 375340}, "timestamps": {"to": "00:06:16,700", "from": "00:06:15,340"}}, {"text": "Где я?", "offsets": {"to": 377180, "from": 376700}, "timestamps": {"to": "00:06:17,180", "from": "00:06:16,700"}}, {"text": "Где я это делал?", "offsets": {"to": 378460, "from": 377180}, "timestamps": {"to": "00:06:18,460", "from": "00:06:17,180"}}, {"text": "Где-то я здесь это писал.", "offsets": {"to": 382800, "from": 378460}, "timestamps": {"to": "00:06:22,800", "from": "00:06:18,460"}}, {"text": "А, вот, Snapshot Isolation.", "offsets": {"to": 384520, "from": 382800}, "timestamps": {"to": "00:06:24,520", "from": "00:06:22,800"}}, {"text": "Видите, SSI, Snapshot Isolation.", "offsets": {"to": 386360, "from": 384520}, "timestamps": {"to": "00:06:26,360", "from": "00:06:24,520"}}, {"text": "А у Serializable, Serializable Snapshot Isolation.", "offsets": {"to": 390960, "from": 386360}, "timestamps": {"to": "00:06:30,960", "from": "00:06:26,360"}}, {"text": "То есть SSI, он будет использоваться только в Serializable, на остальных уровнях его нет.", "offsets": {"to": 397880, "from": 392020}, "timestamps": {"to": "00:06:37,880", "from": "00:06:32,020"}}, {"text": "То есть если мы хотим его включить, вот этот специальный граф, который будет отлавливать вот эти все проблемы синхронизации, то это вот мы включаем Serializable.", "offsets": {"to": 409820, "from": 397880}, "timestamps": {"to": "00:06:49,820", "from": "00:06:37,880"}}, {"text": "Вот.", "offsets": {"to": 410940, "from": 410340}, "timestamps": {"to": "00:06:50,940", "from": "00:06:50,340"}}, {"text": "Если мы имеем шестое Serializable транзакцию, мы ее включили, то в принципе нам уже не обязательно использовать SelectForUpdate блоки, потому что SelectForUpdate он лочит.", "offsets": {"to": 423160, "from": 410940}, "timestamps": {"to": "00:07:03,160", "from": "00:06:50,940"}}, {"text": "А у нас уже по сути Serializable и уровень изоляции, он обрабатывает эту ситуацию уже.", "offsets": {"to": 429760, "from": 423160}, "timestamps": {"to": "00:07:09,760", "from": "00:07:03,160"}}, {"text": "То есть нам не надо лочить, потому что мы будем и там нагрузку увеличивать, то есть Serializable будет это все делать.", "offsets": {"to": 436300, "from": 430340}, "timestamps": {"to": "00:07:16,300", "from": "00:07:10,340"}}, {"text": "И еще параллельно мы будем лочить, ну то есть вдвойне.", "offsets": {"to": 439620, "from": 436300}, "timestamps": {"to": "00:07:19,620", "from": "00:07:16,300"}}, {"text": "И поэтому рекомендуют даже официальный Postgres документация, рекомендуют убирать их тогда.", "offsets": {"to": 445720, "from": 439620}, "timestamps": {"to": "00:07:25,720", "from": "00:07:19,620"}}, {"text": "И по возможности включать изоляцию, если это возможно, да, если есть такая possibility, как Redon или транзакцию.", "offsets": {"to": 455600, "from": 446200}, "timestamps": {"to": "00:07:35,600", "from": "00:07:26,200"}}, {"text": "Например, если она не меняет никакие данные.", "offsets": {"to": 458240, "from": 455600}, "timestamps": {"to": "00:07:38,240", "from": "00:07:35,600"}}, {"text": "Вот.", "offsets": {"to": 459220, "from": 458240}, "timestamps": {"to": "00:07:39,220", "from": "00:07:38,240"}}, {"text": "Таким образом Postgres может обеспечивать более высокую производительность.", "offsets": {"to": 464200, "from": 459220}, "timestamps": {"to": "00:07:44,200", "from": "00:07:39,220"}}, {"text": "Он будет понимать, что транзакция ничего не меняет.", "offsets": {"to": 466620, "from": 464200}, "timestamps": {"to": "00:07:46,620", "from": "00:07:44,200"}}, {"text": "И он может отсекать разные вот эти Predicate Locks, которые вообще не нужны.", "offsets": {"to": 471580, "from": 466620}, "timestamps": {"to": "00:07:51,580", "from": "00:07:46,620"}}, {"text": "Новорайд, например, да, какие-то.", "offsets": {"to": 473380, "from": 471640}, "timestamps": {"to": "00:07:53,380", "from": "00:07:51,640"}}, {"text": "И может идти по более оптимальному пути.", "offsets": {"to": 476580, "from": 473380}, "timestamps": {"to": "00:07:56,580", "from": "00:07:53,380"}}, {"text": "Вот.", "offsets": {"to": 477700, "from": 476580}, "timestamps": {"to": "00:07:57,700", "from": "00:07:56,580"}}, {"text": "Более быстрому.", "offsets": {"to": 479020, "from": 477700}, "timestamps": {"to": "00:07:59,020", "from": "00:07:57,700"}}, {"text": "Меньше проблем, меньше ошибок будет от лупов нашей транзакции.", "offsets": {"to": 484480, "from": 479020}, "timestamps": {"to": "00:08:04,480", "from": "00:07:59,020"}}, {"text": "Да.", "offsets": {"to": 487340, "from": 484480}, "timestamps": {"to": "00:08:07,340", "from": "00:08:04,480"}}, {"text": "Следующее это то, что если возможно, нужно использовать Connection Pool.", "offsets": {"to": 491940, "from": 487340}, "timestamps": {"to": "00:08:11,940", "from": "00:08:07,340"}}, {"text": "Типа держать пул каких-то соединений из нашей базы данных.", "offsets": {"to": 497440, "from": 491940}, "timestamps": {"to": "00:08:17,440", "from": "00:08:11,940"}}, {"text": "И брать каждое новое соединение из этого пула.", "offsets": {"to": 499900, "from": 497440}, "timestamps": {"to": "00:08:19,900", "from": "00:08:17,440"}}, {"text": "То есть, чтобы Connection не пересоздавался постоянно, если у вас High Load какой-то, а переиспользовалось просто.", "offsets": {"to": 506960, "from": 500340}, "timestamps": {"to": "00:08:26,960", "from": "00:08:20,340"}}, {"text": "Ну, то есть, это будет быстрее, нагрузка будет уже меньше на вот эти постоянные установки соединений.", "offsets": {"to": 511840, "from": 506960}, "timestamps": {"to": "00:08:31,840", "from": "00:08:26,960"}}, {"text": "Также не используйте Long Running Transaction.", "offsets": {"to": 516020, "from": 511840}, "timestamps": {"to": "00:08:36,020", "from": "00:08:31,840"}}, {"text": "То есть, транзакция, которая выполняется очень долго.", "offsets": {"to": 519520, "from": 516020}, "timestamps": {"to": "00:08:39,520", "from": "00:08:36,020"}}, {"text": "То есть, транзакция, она вообще, какое правило у нее?", "offsets": {"to": 523180, "from": 519520}, "timestamps": {"to": "00:08:43,180", "from": "00:08:39,520"}}, {"text": "Она должна выполняться как можно меньше.", "offsets": {"to": 525140, "from": 523180}, "timestamps": {"to": "00:08:45,140", "from": "00:08:43,180"}}, {"text": "То есть, та область, где она работает, должна быть максимально узкой.", "offsets": {"to": 529840, "from": 525340}, "timestamps": {"to": "00:08:49,840", "from": "00:08:45,340"}}, {"text": "Это то же самое, как в мультитрейдинге.", "offsets": {"to": 532860, "from": 529840}, "timestamps": {"to": "00:08:52,860", "from": "00:08:49,840"}}, {"text": "Мы когда локи ставим, мы стараемся вообще везде их ставить и там кучу всего делать.", "offsets": {"to": 537660, "from": 532860}, "timestamps": {"to": "00:08:57,660", "from": "00:08:52,860"}}, {"text": "Ну, тоже на самом деле, может, так безопаснее, конечно.", "offsets": {"to": 540800, "from": 537660}, "timestamps": {"to": "00:09:00,800", "from": "00:08:57,660"}}, {"text": "Но если есть возможность, мы пытаемся заложить какую-то Critical Area,", "offsets": {"to": 545140, "from": 540800}, "timestamps": {"to": "00:09:05,140", "from": "00:09:00,800"}}, {"text": "которая конфликтует вот это с другими потоками, как можно меньше.", "offsets": {"to": 549520, "from": 545220}, "timestamps": {"to": "00:09:09,520", "from": "00:09:05,220"}}, {"text": "И здесь мы тоже стараемся сделать транзакцию как можно меньше, чтобы она быстро отработала и все.", "offsets": {"to": 554580, "from": 549520}, "timestamps": {"to": "00:09:14,580", "from": "00:09:09,520"}}, {"text": "Потому что долгие транзакции, они будут жрать очень много ресурсов,", "offsets": {"to": 559340, "from": 554580}, "timestamps": {"to": "00:09:19,340", "from": "00:09:14,580"}}, {"text": "они очень много проблем могут создать BD.", "offsets": {"to": 562820, "from": 559340}, "timestamps": {"to": "00:09:22,820", "from": "00:09:19,340"}}, {"text": "Они там это все хранят, у них там есть лог свой, копии данных своих.", "offsets": {"to": 570000, "from": 564740}, "timestamps": {"to": "00:09:30,000", "from": "00:09:24,740"}}, {"text": "А представьте, у вас это все долго хранится и тысячи транзакций меняют все постоянно.", "offsets": {"to": 574780, "from": 570000}, "timestamps": {"to": "00:09:34,780", "from": "00:09:30,000"}}, {"text": "Ну, то есть, вот, там есть специальные механизмы чисток и так далее этого всего,", "offsets": {"to": 582200, "from": 574780}, "timestamps": {"to": "00:09:42,200", "from": "00:09:34,780"}}, {"text": "которые могут занимать время и которые, например, если у вас очень долго были транзакции,", "offsets": {"to": 587120, "from": 582200}, "timestamps": {"to": "00:09:47,120", "from": "00:09:42,200"}}, {"text": "у вас все эти журналы перекопились там, да, временные и так далее,", "offsets": {"to": 591340, "from": 587120}, "timestamps": {"to": "00:09:51,340", "from": "00:09:47,120"}}, {"text": "у вас может даже лочить таблицу или полностью база даже может остановиться, да,", "offsets": {"to": 597280, "from": 591560}, "timestamps": {"to": "00:09:57,280", "from": "00:09:51,560"}}, {"text": "чтобы начать вот эту чистку и потом снова базу можно будет поднять и запустить.", "offsets": {"to": 601780, "from": 597280}, "timestamps": {"to": "00:10:01,780", "from": "00:09:57,280"}}, {"text": "Или таблица может застыть, чтобы это все почистить.", "offsets": {"to": 606640, "from": 601780}, "timestamps": {"to": "00:10:06,640", "from": "00:10:01,780"}}, {"text": "Вот.", "offsets": {"to": 608380, "from": 606640}, "timestamps": {"to": "00:10:08,380", "from": "00:10:06,640"}}, {"text": "Поэтому стараться как можно меньше времени их использовать.", "offsets": {"to": 612540, "from": 608380}, "timestamps": {"to": "00:10:12,540", "from": "00:10:08,380"}}, {"text": "Запустили, отработали, все.", "offsets": {"to": 614080, "from": 612540}, "timestamps": {"to": "00:10:14,080", "from": "00:10:12,540"}}, {"text": "Например, запрос начался, быстренько отработали, запрос завершился,", "offsets": {"to": 618060, "from": 614080}, "timestamps": {"to": "00:10:18,060", "from": "00:10:14,080"}}, {"text": "отработали, все, завершили транзакцию.", "offsets": {"to": 620920, "from": 618060}, "timestamps": {"to": "00:10:20,920", "from": "00:10:18,060"}}, {"text": "Они держим ее там очень-очень долго на несколько запросов.", "offsets": {"to": 626320, "from": 621360}, "timestamps": {"to": "00:10:26,320", "from": "00:10:21,360"}}, {"text": "Так, да.", "offsets": {"to": 627160, "from": 626320}, "timestamps": {"to": "00:10:27,160", "from": "00:10:26,320"}}, {"text": "И еще, смотрите, я нашел...", "offsets": {"to": 629080, "from": 627160}, "timestamps": {"to": "00:10:29,080", "from": "00:10:27,160"}}, {"text": "Все, я уже опять в 2 часа.", "offsets": {"to": 631600, "from": 629080}, "timestamps": {"to": "00:10:31,600", "from": "00:10:29,080"}}, {"text": "Точно никто смотреть не будет.", "offsets": {"to": 633360, "from": 631600}, "timestamps": {"to": "00:10:33,360", "from": "00:10:31,600"}}, {"text": "Ну, короче...", "offsets": {"to": 635140, "from": 633360}, "timestamps": {"to": "00:10:35,140", "from": "00:10:33,360"}}, {"text": "Ну, да ладно.", "offsets": {"to": 635740, "from": 635140}, "timestamps": {"to": "00:10:35,740", "from": "00:10:35,140"}}, {"text": "Короче, я еще нашел один интересный ресерч.", "offsets": {"to": 641360, "from": 635740}, "timestamps": {"to": "00:10:41,360", "from": "00:10:35,740"}}, {"text": "High-Performance Transaction via Early Write Visibility 2017 года.", "offsets": {"to": 647060, "from": 641880}, "timestamps": {"to": "00:10:47,060", "from": "00:10:41,880"}}, {"text": "И там чуваки, они проводили разные эксперименты, они исследуют постоянно вот это все.", "offsets": {"to": 652440, "from": 647060}, "timestamps": {"to": "00:10:52,440", "from": "00:10:47,060"}}, {"text": "И они придумали специальный алгоритм, вот этот вот PWE, который у них показал, значительно увеличил производительность уровня Serializable транзакции,", "offsets": {"to": 665720, "from": 652960}, "timestamps": {"to": "00:11:05,720", "from": "00:10:52,960"}}, {"text": "что он в некоторых кейсов стал примерно такой же быстрый, как и Read Committed.", "offsets": {"to": 671720, "from": 666600}, "timestamps": {"to": "00:11:11,720", "from": "00:11:06,600"}}, {"text": "То есть, представляете, да, то есть они увеличили, ускорили Serializable настолько, что в каких-то процентных, ну, в каких-то областях применения, да, там, на Read''ах и так далее, в Write''е они оптимизируют как можно быстрее, да, там, то есть, если мы знаем, что уже можно запись делать, там, уже он быстро делает и все.", "offsets": {"to": 694920, "from": 672400}, "timestamps": {"to": "00:11:34,920", "from": "00:11:12,400"}}, {"text": "Ну, то есть, как можно быстрее дать понять другим транзакциям, что происходит.", "offsets": {"to": 699000, "from": 694920}, "timestamps": {"to": "00:11:39,000", "from": "00:11:34,920"}}, {"text": "И они придумали специальный вот такой вот алгоритм по такой системе, который позволяет как можно быстрее отсекать другие транзакции, например, да, либо, наоборот, им давать работать, дать понять, что нет проблем.", "offsets": {"to": 712040, "from": 699000}, "timestamps": {"to": "00:11:52,040", "from": "00:11:39,000"}}, {"text": "И он реально там все ускоряет у них, и по уровню даже доходит до Read Committed, то есть, можете тоже погулить, почитать, может, тоже что-то интересное напишите, и в комментах мне дополнения какие-то скажете.", "offsets": {"to": 724640, "from": 712040}, "timestamps": {"to": "00:12:04,640", "from": "00:11:52,040"}}, {"text": "может, я вру, а он все сейчас вообще...", "offsets": {"to": 726640, "from": 724640}, "timestamps": {"to": "00:12:06,640", "from": "00:12:04,640"}}, {"text": "Ну, короче, вот, я там оттуда вот это вот взял, прочитал.", "offsets": {"to": 730920, "from": 726640}, "timestamps": {"to": "00:12:10,920", "from": "00:12:06,640"}}, {"text": "Вот, про перформанс мы уже...", "offsets": {"to": 732980, "from": 730920}, "timestamps": {"to": "00:12:12,980", "from": "00:12:10,920"}}]}',NULL,NULL),
	 ('52c9dc45-d72f-4a28-987b-c42b85525d18','24. SSI Performance.mp3','SQL_ISOLATIONS','2026-04-10 12:15:03.974',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "сказали из другого ресёрча, так, типы.", "offsets": {"to": 3980, "from": 0}, "timestamps": {"to": "00:00:03,980", "from": "00:00:00,000"}}]}',NULL,NULL),
	 ('92c705d5-ebf4-420e-869d-1707d38ad975','25. Concurrency Control Types.mp3','SQL_ISOLATIONS','2026-04-10 12:15:16.775',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Да, напоследок, вот совсем немножко осталось,", "offsets": {"to": 3480, "from": 0}, "timestamps": {"to": "00:00:03,480", "from": "00:00:00,000"}}, {"text": "типа, какие есть типы контроля concurrency,", "offsets": {"to": 6340, "from": 3480}, "timestamps": {"to": "00:00:06,340", "from": "00:00:03,480"}}, {"text": "которые я вот упоминал, да, в базе данных на serializable,", "offsets": {"to": 10380, "from": 6340}, "timestamps": {"to": "00:00:10,380", "from": "00:00:06,340"}}, {"text": "на repeatable read, да, у нас есть определенные типы,", "offsets": {"to": 14400, "from": 10380}, "timestamps": {"to": "00:00:14,400", "from": "00:00:10,380"}}, {"text": "которые применяются, pessimistic, оптимистик,", "offsets": {"to": 16460, "from": 14400}, "timestamps": {"to": "00:00:16,460", "from": "00:00:14,400"}}, {"text": "pessimistic это обычно используется в environment,", "offsets": {"to": 21400, "from": 16460}, "timestamps": {"to": "00:00:21,400", "from": "00:00:16,460"}}, {"text": "где у нас очень high contention of data называется,", "offsets": {"to": 26280, "from": 21400}, "timestamps": {"to": "00:00:26,280", "from": "00:00:21,400"}}, {"text": "вот он, high contention of data,", "offsets": {"to": 29220, "from": 26280}, "timestamps": {"to": "00:00:29,220", "from": "00:00:26,280"}}, {"text": "это когда много, много потоков одни и те же данные используют,", "offsets": {"to": 33840, "from": 29620}, "timestamps": {"to": "00:00:33,840", "from": "00:00:29,620"}}, {"text": "и там очень хорошо использовать как раз вот pessimistic,", "offsets": {"to": 37460, "from": 33840}, "timestamps": {"to": "00:00:37,460", "from": "00:00:33,840"}}, {"text": "чтобы они просто остальные подождали, вот,", "offsets": {"to": 40720, "from": 37460}, "timestamps": {"to": "00:00:40,720", "from": "00:00:37,460"}}, {"text": "и начали по одной ждали, и потом доступ получали,", "offsets": {"to": 44460, "from": 40720}, "timestamps": {"to": "00:00:44,460", "from": "00:00:40,720"}}, {"text": "то есть не было вот этих постоянных ретраев,", "offsets": {"to": 46900, "from": 44460}, "timestamps": {"to": "00:00:46,900", "from": "00:00:44,460"}}, {"text": "миллионов ретраев,", "offsets": {"to": 48460, "from": 46900}, "timestamps": {"to": "00:00:48,460", "from": "00:00:46,900"}}, {"text": "оптимистик используется, когда у нас не очень contention высокий,", "offsets": {"to": 53700, "from": 48460}, "timestamps": {"to": "00:00:53,700", "from": "00:00:48,460"}}, {"text": "он low contention for data,", "offsets": {"to": 55900, "from": 53700}, "timestamps": {"to": "00:00:55,900", "from": "00:00:53,700"}}, {"text": "и наши транзакции, они будут, например,", "offsets": {"to": 59400, "from": 55900}, "timestamps": {"to": "00:00:59,400", "from": "00:00:55,900"}}, {"text": "могут ралбэчиться, но, ну, как время от времени,", "offsets": {"to": 62740, "from": 59500}, "timestamps": {"to": "00:01:02,740", "from": "00:00:59,500"}}, {"text": "не так много, ну, ралбэчиться, да, ралбэчиться, и хрен с ними,", "offsets": {"to": 65540, "from": 62740}, "timestamps": {"to": "00:01:05,540", "from": "00:01:02,740"}}, {"text": "вот, и как бы там пару раз, там, да, окей,", "offsets": {"to": 70260, "from": 65540}, "timestamps": {"to": "00:01:10,260", "from": "00:01:05,540"}}, {"text": "несколько потоков, например, в конфликте,", "offsets": {"to": 74320, "from": 70260}, "timestamps": {"to": "00:01:14,320", "from": "00:01:10,260"}}, {"text": "конфликты, они просто переповторили, и все хорошо,", "offsets": {"to": 77620, "from": 74320}, "timestamps": {"to": "00:01:17,620", "from": "00:01:14,320"}}, {"text": "вот.", "offsets": {"to": 79040, "from": 77620}, "timestamps": {"to": "00:01:19,040", "from": "00:01:17,620"}}, {"text": "локинг есть, и он применяется в пессимистике, да,", "offsets": {"to": 82580, "from": 79720}, "timestamps": {"to": "00:01:22,580", "from": "00:01:19,720"}}, {"text": "то есть мы лочим либо таблицу, либо rows, либо pages,", "offsets": {"to": 86440, "from": 82580}, "timestamps": {"to": "00:01:26,440", "from": "00:01:22,580"}}, {"text": "разные ресурсы, или базу там вообще,", "offsets": {"to": 89660, "from": 86440}, "timestamps": {"to": "00:01:29,660", "from": "00:01:26,440"}}, {"text": "то есть, и разные транзакции как раз на этих локах останавливаются и ждут,", "offsets": {"to": 95620, "from": 89660}, "timestamps": {"to": "00:01:35,620", "from": "00:01:29,660"}}, {"text": "то есть каждый локон блокирует другие транзакции,", "offsets": {"to": 99180, "from": 96180}, "timestamps": {"to": "00:01:39,180", "from": "00:01:36,180"}}, {"text": "чтобы они не могли ни читать, ни модифицировать,", "offsets": {"to": 101940, "from": 99180}, "timestamps": {"to": "00:01:41,940", "from": "00:01:39,180"}}, {"text": "ничего с ними вообще делать, вот.", "offsets": {"to": 104680, "from": 101940}, "timestamps": {"to": "00:01:44,680", "from": "00:01:41,940"}}, {"text": "Когда транзакция будет завершена,", "offsets": {"to": 107680, "from": 105920}, "timestamps": {"to": "00:01:47,680", "from": "00:01:45,920"}}, {"text": "налог освобождает, как ньютекс,", "offsets": {"to": 109160, "from": 107680}, "timestamps": {"to": "00:01:49,160", "from": "00:01:47,680"}}, {"text": "и другие могут зайти поиспользовать наши данные.", "offsets": {"to": 111860, "from": 109160}, "timestamps": {"to": "00:01:51,860", "from": "00:01:49,160"}}, {"text": "Версионность мы каждой, грубо говоря, строке добавляем", "offsets": {"to": 116980, "from": 111860}, "timestamps": {"to": "00:01:56,980", "from": "00:01:51,860"}}, {"text": "какую-то версию, и по этой версии мы можем понимать,", "offsets": {"to": 119680, "from": 116980}, "timestamps": {"to": "00:01:59,680", "from": "00:01:56,980"}}, {"text": "менялась строка или не менялась.", "offsets": {"to": 122220, "from": 119680}, "timestamps": {"to": "00:02:02,220", "from": "00:01:59,680"}}, {"text": "То есть, если наша текущая версия отличается от той,", "offsets": {"to": 125420, "from": 122220}, "timestamps": {"to": "00:02:05,420", "from": "00:02:02,220"}}, {"text": "что в базе лежит, да, а в нашей транзакции другая вообще,", "offsets": {"to": 129760, "from": 125420}, "timestamps": {"to": "00:02:09,760", "from": "00:02:05,420"}}, {"text": "мы понимаем, что, ну, наша версия не соответствует,", "offsets": {"to": 133580, "from": 129760}, "timestamps": {"to": "00:02:13,580", "from": "00:02:09,760"}}, {"text": "что-то уже поменяла, какая-то что-то другое поменяла.", "offsets": {"to": 137160, "from": 133860}, "timestamps": {"to": "00:02:17,160", "from": "00:02:13,860"}}, {"text": "И, соответственно, мы говорим, что всё, извини,", "offsets": {"to": 140240, "from": 137160}, "timestamps": {"to": "00:02:20,240", "from": "00:02:17,160"}}, {"text": "но что-то поменяло, что-то влезло параллельно,", "offsets": {"to": 144240, "from": 140240}, "timestamps": {"to": "00:02:24,240", "from": "00:02:20,240"}}, {"text": "и поэтому начни сначала, пожалуйста.", "offsets": {"to": 146440, "from": 144240}, "timestamps": {"to": "00:02:26,440", "from": "00:02:24,240"}}, {"text": "Вот, называется «Ровая вершина».", "offsets": {"to": 150240, "from": 146440}, "timestamps": {"to": "00:02:30,240", "from": "00:02:26,440"}}, {"text": "Ровая вершина.", "offsets": {"to": 152000, "from": 150240}, "timestamps": {"to": "00:02:32,000", "from": "00:02:30,240"}}]}',NULL,NULL),
	 ('fc3a1fb9-b16a-4335-8197-af6de677df67','26. Isolation Levels are not always an answer.mp3','SQL_ISOLATIONS','2026-04-10 12:15:43.861',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "разные вершины, на каждый ролл добавляется.", "offsets": {"to": 3520, "from": 0}, "timestamps": {"to": "00:00:03,520", "from": "00:00:00,000"}}, {"text": "Также он применяется немножко ещё в других ситуациях.", "offsets": {"to": 6380, "from": 3520}, "timestamps": {"to": "00:00:06,380", "from": "00:00:03,520"}}, {"text": "Об этом я буду в следующем теоретическом видео рассказывать.", "offsets": {"to": 10640, "from": 6380}, "timestamps": {"to": "00:00:10,640", "from": "00:00:06,380"}}, {"text": "Она будет тоже, посмотрите, интересная.", "offsets": {"to": 12460, "from": 10640}, "timestamps": {"to": "00:00:12,460", "from": "00:00:10,640"}}, {"text": "То есть вся вот эта информация, что сегодня была, мы её заюзаем.", "offsets": {"to": 16100, "from": 12460}, "timestamps": {"to": "00:00:16,100", "from": "00:00:12,460"}}, {"text": "Мы заюзаем в следующем видео, прям практически это всё накодим.", "offsets": {"to": 19860, "from": 16100}, "timestamps": {"to": "00:00:19,860", "from": "00:00:16,100"}}, {"text": "А потом заюзаем ещё раз и найдём множество разных способов,", "offsets": {"to": 25680, "from": 19860}, "timestamps": {"to": "00:00:25,680", "from": "00:00:19,860"}}, {"text": "как избежать этого всего.", "offsets": {"to": 27000, "from": 25680}, "timestamps": {"to": "00:00:27,000", "from": "00:00:25,680"}}, {"text": "Как нам вообще каждый день кодировать, да, программу писать,", "offsets": {"to": 30800, "from": 27460}, "timestamps": {"to": "00:00:30,800", "from": "00:00:27,460"}}, {"text": "чтобы убрать вот эту всю парашу.", "offsets": {"to": 32640, "from": 30800}, "timestamps": {"to": "00:00:32,640", "from": "00:00:30,800"}}, {"text": "Ну, типа, чтобы нам проще, короче, было.", "offsets": {"to": 34720, "from": 32640}, "timestamps": {"to": "00:00:34,720", "from": "00:00:32,640"}}, {"text": "И я там разные способы переберу.", "offsets": {"to": 36380, "from": 34720}, "timestamps": {"to": "00:00:36,380", "from": "00:00:34,720"}}, {"text": "Типа, тоже интересно будет.", "offsets": {"to": 38860, "from": 36380}, "timestamps": {"to": "00:00:38,860", "from": "00:00:36,380"}}, {"text": "Вот.", "offsets": {"to": 39820, "from": 38860}, "timestamps": {"to": "00:00:39,820", "from": "00:00:38,860"}}, {"text": "Да.", "offsets": {"to": 41860, "from": 39820}, "timestamps": {"to": "00:00:41,860", "from": "00:00:39,820"}}, {"text": "Есть разные ситуации.", "offsets": {"to": 44480, "from": 41860}, "timestamps": {"to": "00:00:44,480", "from": "00:00:41,860"}}, {"text": "Read, modify, write, operations.", "offsets": {"to": 46060, "from": 44480}, "timestamps": {"to": "00:00:46,060", "from": "00:00:44,480"}}, {"text": "То есть последний слайд называется isolation levels are not always an answer.", "offsets": {"to": 52860, "from": 46060}, "timestamps": {"to": "00:00:52,860", "from": "00:00:46,060"}}, {"text": "То есть не всегда это ответ.", "offsets": {"to": 54780, "from": 52860}, "timestamps": {"to": "00:00:54,780", "from": "00:00:52,860"}}, {"text": "Они не всегда вам помогут.", "offsets": {"to": 56940, "from": 54780}, "timestamps": {"to": "00:00:56,940", "from": "00:00:54,780"}}, {"text": "Есть разные операции, которые дистрибьют, да,", "offsets": {"to": 60960, "from": 57460}, "timestamps": {"to": "00:01:00,960", "from": "00:00:57,460"}}, {"text": "разграничены во времени, например.", "offsets": {"to": 63260, "from": 60960}, "timestamps": {"to": "00:01:03,260", "from": "00:01:00,960"}}, {"text": "И сначала будет чтение, потом через какое-то, через пять минут будет запись.", "offsets": {"to": 69120, "from": 63260}, "timestamps": {"to": "00:01:09,120", "from": "00:01:03,260"}}, {"text": "Вы не сможете транзакцию столько держать.", "offsets": {"to": 70800, "from": 69120}, "timestamps": {"to": "00:01:10,800", "from": "00:01:09,120"}}, {"text": "И это всё может lost update вызвать.", "offsets": {"to": 73640, "from": 70800}, "timestamps": {"to": "00:01:13,640", "from": "00:01:10,800"}}, {"text": "У вас просто с веба приходят параллельно запросы lost update.", "offsets": {"to": 76940, "from": 73640}, "timestamps": {"to": "00:01:16,940", "from": "00:01:13,640"}}, {"text": "И всё, транзакцию не заюзайте.", "offsets": {"to": 79080, "from": 76940}, "timestamps": {"to": "00:01:19,080", "from": "00:01:16,940"}}, {"text": "Она не поможет, какой бы вы ни сделали.", "offsets": {"to": 81140, "from": 79080}, "timestamps": {"to": "00:01:21,140", "from": "00:01:19,080"}}, {"text": "Вот.", "offsets": {"to": 82600, "from": 81140}, "timestamps": {"to": "00:01:22,600", "from": "00:01:21,140"}}, {"text": "Высокий уровень транзакций уменьшает concurrency.", "offsets": {"to": 86020, "from": 82600}, "timestamps": {"to": "00:01:26,020", "from": "00:01:22,600"}}, {"text": "Я вот сейчас рассказал, что storm of retrace может вызвать,", "offsets": {"to": 89360, "from": 86020}, "timestamps": {"to": "00:01:29,360", "from": "00:01:26,020"}}, {"text": "который будет грузить очень сильно всю систему.", "offsets": {"to": 91820, "from": 89360}, "timestamps": {"to": "00:01:31,820", "from": "00:01:29,360"}}, {"text": "Без конца просто.", "offsets": {"to": 93300, "from": 91820}, "timestamps": {"to": "00:01:33,300", "from": "00:01:31,820"}}, {"text": "То есть у вас там миллионы, тысячи, потом две тысячи.", "offsets": {"to": 96400, "from": 93300}, "timestamps": {"to": "00:01:36,400", "from": "00:01:33,300"}}, {"text": "Они всё летят и летят, а они всё ретраятся и не успевают.", "offsets": {"to": 99900, "from": 97060}, "timestamps": {"to": "00:01:39,900", "from": "00:01:37,060"}}, {"text": "Ретраятся, ретраятся.", "offsets": {"to": 100980, "from": 99900}, "timestamps": {"to": "00:01:40,980", "from": "00:01:39,900"}}, {"text": "Они всё новые, например, прилетают.", "offsets": {"to": 103240, "from": 100980}, "timestamps": {"to": "00:01:43,240", "from": "00:01:40,980"}}, {"text": "Они всё продолжают вот так ретраяться и перезапускаться.", "offsets": {"to": 106320, "from": 103240}, "timestamps": {"to": "00:01:46,320", "from": "00:01:43,240"}}, {"text": "Вот.", "offsets": {"to": 107560, "from": 106320}, "timestamps": {"to": "00:01:47,560", "from": "00:01:46,320"}}, {"text": "И получается, как storm of retrace.", "offsets": {"to": 109620, "from": 107560}, "timestamps": {"to": "00:01:49,620", "from": "00:01:47,560"}}, {"text": "Да.", "offsets": {"to": 110820, "from": 110480}, "timestamps": {"to": "00:01:50,820", "from": "00:01:50,480"}}, {"text": "Чтобы правильно выбрать транзакцию, нужно, ну, собственно, правильно её выбирать.", "offsets": {"to": 115700, "from": 110820}, "timestamps": {"to": "00:01:55,700", "from": "00:01:50,820"}}, {"text": "Выбирать либо транзакцию, либо какой-то log, row log, table log.", "offsets": {"to": 120880, "from": 115700}, "timestamps": {"to": "00:02:00,880", "from": "00:01:55,700"}}, {"text": "Может быть, выбирать какие-то atomic updates.", "offsets": {"to": 122960, "from": 120880}, "timestamps": {"to": "00:02:02,960", "from": "00:02:00,880"}}, {"text": "Это тоже.", "offsets": {"to": 123440, "from": 122960}, "timestamps": {"to": "00:02:03,440", "from": "00:02:02,960"}}, {"text": "Я потом всё расскажу.", "offsets": {"to": 124480, "from": 123440}, "timestamps": {"to": "00:02:04,480", "from": "00:02:03,440"}}, {"text": "Оптимистик, пессимистик.", "offsets": {"to": 126000, "from": 124480}, "timestamps": {"to": "00:02:06,000", "from": "00:02:04,480"}}, {"text": "Read, modify, write, problems, как избежать.", "offsets": {"to": 129080, "from": 126000}, "timestamps": {"to": "00:02:09,080", "from": "00:02:06,000"}}, {"text": "Это всё мы тоже рассмотрим в следующем видео.", "offsets": {"to": 131960, "from": 129080}, "timestamps": {"to": "00:02:11,960", "from": "00:02:09,080"}}, {"text": "Это было вот такое интересное видео.", "offsets": {"to": 134080, "from": 131960}, "timestamps": {"to": "00:02:14,080", "from": "00:02:11,960"}}, {"text": "Вообще, что бывает.", "offsets": {"to": 135120, "from": 134080}, "timestamps": {"to": "00:02:15,120", "from": "00:02:14,080"}}, {"text": "Чтобы потом, когда вы вдруг будете там работать, что-то делать,", "offsets": {"to": 140360, "from": 135120}, "timestamps": {"to": "00:02:20,360", "from": "00:02:15,120"}}, {"text": "и у вас бан, и вы такие, ёпта, да это же в rights queue.", "offsets": {"to": 144160, "from": 140360}, "timestamps": {"to": "00:02:24,160", "from": "00:02:20,360"}}, {"text": "Пишите там всем, это в rights queue.", "offsets": {"to": 147380, "from": 144160}, "timestamps": {"to": "00:02:27,380", "from": "00:02:24,160"}}, {"text": "И они всё, вау, ничего себе, откуда он это знает.", "offsets": {"to": 149400, "from": 147380}, "timestamps": {"to": "00:02:29,400", "from": "00:02:27,380"}}, {"text": "Ну, ладно.", "offsets": {"to": 150700, "from": 149400}, "timestamps": {"to": "00:02:30,700", "from": "00:02:29,400"}}, {"text": "Вот только для этого.", "offsets": {"to": 153040, "from": 150700}, "timestamps": {"to": "00:02:33,040", "from": "00:02:30,700"}}, {"text": "Короче, вы это всё вспомните, и вам будет проще просто", "offsets": {"to": 157460, "from": 153040}, "timestamps": {"to": "00:02:37,460", "from": "00:02:33,040"}}, {"text": "помнить и принять какое-то решение, да,", "offsets": {"to": 160040, "from": 157460}, "timestamps": {"to": "00:02:40,040", "from": "00:02:37,460"}}, {"text": "думать, что, наверное, надо как-то залучить там или так далее,", "offsets": {"to": 163220, "from": 160040}, "timestamps": {"to": "00:02:43,220", "from": "00:02:40,040"}}, {"text": "что это не что-то магическое.", "offsets": {"to": 166020, "from": 163220}, "timestamps": {"to": "00:02:46,020", "from": "00:02:43,220"}}, {"text": "Да, и самый последний, типа, совет, это очень хорошо иметь", "offsets": {"to": 170240, "from": 166020}, "timestamps": {"to": "00:02:50,240", "from": "00:02:46,020"}}, {"text": "департамент DBA, который занимается базами данных,", "offsets": {"to": 173220, "from": 170240}, "timestamps": {"to": "00:02:53,220", "from": "00:02:50,240"}}, {"text": "потому что обычный программист-разработчик,", "offsets": {"to": 175340, "from": 173220}, "timestamps": {"to": "00:02:55,340", "from": "00:02:53,220"}}, {"text": "какой бы он хороший ни был, скорее всего,", "offsets": {"to": 176940, "from": 175340}, "timestamps": {"to": "00:02:56,940", "from": "00:02:55,340"}}, {"text": "не будет знать большинство вещей, которые я сегодня рассказал,", "offsets": {"to": 180180, "from": 176940}, "timestamps": {"to": "00:03:00,180", "from": "00:02:56,940"}}, {"text": "а уж помнить о них точно, наверное, не будет.", "offsets": {"to": 183080, "from": 180180}, "timestamps": {"to": "00:03:03,080", "from": "00:03:00,180"}}, {"text": "И поэтому очень полезно, ну, потому что очень много информации.", "offsets": {"to": 186040, "from": 183080}, "timestamps": {"to": "00:03:06,040", "from": "00:03:03,080"}}, {"text": "хорошо сейчас, в современном мире создавать департаменты,", "offsets": {"to": 191300, "from": 188040}, "timestamps": {"to": "00:03:11,300", "from": "00:03:08,040"}}, {"text": "которые занимаются, например, только базами данных DBA,", "offsets": {"to": 193800, "from": 191300}, "timestamps": {"to": "00:03:13,800", "from": "00:03:11,300"}}, {"text": "чтобы они оптимизировали ваши запросы, если, ну, как лучше написать,", "offsets": {"to": 198080, "from": 193800}, "timestamps": {"to": "00:03:18,080", "from": "00:03:13,800"}}, {"text": "где лочку поставить, где пессимистик-оптимистик, где какие-то там,", "offsets": {"to": 201640, "from": 198080}, "timestamps": {"to": "00:03:21,640", "from": "00:03:18,080"}}, {"text": "ну, то есть, чтобы человек больше понимал, как лучше в текущей конфигурации базы данных", "offsets": {"to": 206760, "from": 201640}, "timestamps": {"to": "00:03:26,760", "from": "00:03:21,640"}}, {"text": "использовать, грубо говоря, ваши запросы, ваши queries.", "offsets": {"to": 212340, "from": 206760}, "timestamps": {"to": "00:03:32,340", "from": "00:03:26,760"}}, {"text": "То есть, вы что-то напишете, он вам там проверит, модифицирует,", "offsets": {"to": 216380, "from": 212340}, "timestamps": {"to": "00:03:36,380", "from": "00:03:32,340"}}, {"text": "подскажет что-то, например, или скажет, что это вот здесь у нас,", "offsets": {"to": 219860, "from": 216380}, "timestamps": {"to": "00:03:39,860", "from": "00:03:36,380"}}, {"text": "это будет очень плохо, давай переделай на другое там, да,", "offsets": {"to": 222420, "from": 219860}, "timestamps": {"to": "00:03:42,420", "from": "00:03:39,860"}}, {"text": "и вы уже знаете, о чём он говорит после этого видео, да, например,", "offsets": {"to": 226300, "from": 222420}, "timestamps": {"to": "00:03:46,300", "from": "00:03:42,420"}}, {"text": "ну, и после следующего.", "offsets": {"to": 227980, "from": 226300}, "timestamps": {"to": "00:03:47,980", "from": "00:03:46,300"}}, {"text": "Вот, и тогда вы многие из этих проблем будете сбегать просто,", "offsets": {"to": 234240, "from": 228700}, "timestamps": {"to": "00:03:54,240", "from": "00:03:48,700"}}, {"text": "потому что держать это всё в голове, даже вот в ресёрчах я читаю,", "offsets": {"to": 238600, "from": 234240}, "timestamps": {"to": "00:03:58,600", "from": "00:03:54,240"}}, {"text": "и люди пишут, то есть, ресёрчеры, исследователи, что, ну, реально,", "offsets": {"to": 242740, "from": 238600}, "timestamps": {"to": "00:04:02,740", "from": "00:03:58,600"}}, {"text": "среднестатистический человек не будет этого всего помнить,", "offsets": {"to": 247300, "from": 242740}, "timestamps": {"to": "00:04:07,300", "from": "00:04:02,740"}}, {"text": "он не будет знать.", "offsets": {"to": 248180, "from": 247300}, "timestamps": {"to": "00:04:08,180", "from": "00:04:07,300"}}, {"text": "Я даже здесь не полностью все рассказал о аномалии,", "offsets": {"to": 254000, "from": 248180}, "timestamps": {"to": "00:04:14,000", "from": "00:04:08,180"}}, {"text": "есть ещё кое-какие другие, более шизанутые, ну, типа,", "offsets": {"to": 259100, "from": 254000}, "timestamps": {"to": "00:04:19,100", "from": "00:04:14,000"}}, {"text": "прям очень редкие, но они есть, и типа, а может быть,", "offsets": {"to": 263180, "from": 259100}, "timestamps": {"to": "00:04:23,180", "from": "00:04:19,100"}}, {"text": "каких-то вообще не нашли ещё, кто знает.", "offsets": {"to": 265140, "from": 263180}, "timestamps": {"to": "00:04:25,140", "from": "00:04:23,180"}}, {"text": "И типа, поэтому лучше иметь людей, которые занимаются этим", "offsets": {"to": 269040, "from": 265140}, "timestamps": {"to": "00:04:29,040", "from": "00:04:25,140"}}, {"text": "профессионально, и в голове у них это просто постоянно", "offsets": {"to": 272240, "from": 269040}, "timestamps": {"to": "00:04:32,240", "from": "00:04:29,040"}}, {"text": "крутится, и они знают, как лучше в текущей конфигурации", "offsets": {"to": 275380, "from": 272240}, "timestamps": {"to": "00:04:35,380", "from": "00:04:32,240"}}, {"text": "что запускать, как что писать.", "offsets": {"to": 277240, "from": 275380}, "timestamps": {"to": "00:04:37,240", "from": "00:04:35,380"}}, {"text": "Вот, на этом всё, спасибо, что досмотрели до конца,", "offsets": {"to": 281000, "from": 277240}, "timestamps": {"to": "00:04:41,000", "from": "00:04:37,240"}}, {"text": "если есть такие герои, если есть, ставьте лайки,", "offsets": {"to": 283880, "from": 281000}, "timestamps": {"to": "00:04:43,880", "from": "00:04:41,000"}}, {"text": "пишите в комментариях, не бойтесь.", "offsets": {"to": 285500, "from": 283880}, "timestamps": {"to": "00:04:45,500", "from": "00:04:43,880"}}, {"text": "Не забывайте подписываться на Телеграм-канал,", "offsets": {"to": 288720, "from": 285500}, "timestamps": {"to": "00:04:48,720", "from": "00:04:45,500"}}, {"text": "и на Ютубе тоже подписывайтесь, лайки ставьте,", "offsets": {"to": 292380, "from": 288720}, "timestamps": {"to": "00:04:52,380", "from": "00:04:48,720"}}, {"text": "потому что просмотров очень много, там в 2-3 раза больше,", "offsets": {"to": 295100, "from": 292380}, "timestamps": {"to": "00:04:55,100", "from": "00:04:52,380"}}, {"text": "чем лайков и подписок, очень странно.", "offsets": {"to": 298260, "from": 295100}, "timestamps": {"to": "00:04:58,260", "from": "00:04:55,100"}}, {"text": "Поэтому исправляйте это дело, я очень стараюсь подбирать", "offsets": {"to": 301880, "from": 298260}, "timestamps": {"to": "00:05:01,880", "from": "00:04:58,260"}}, {"text": "всю эту информацию, его очень реально много,", "offsets": {"to": 304160, "from": 301880}, "timestamps": {"to": "00:05:04,160", "from": "00:05:01,880"}}, {"text": "зато она очень глубокая, вот такого, ну, нигде не найдёте,", "offsets": {"to": 307860, "from": 304160}, "timestamps": {"to": "00:05:07,860", "from": "00:05:04,160"}}, {"text": "никто этого не делал, я прям специально просмотрел,", "offsets": {"to": 311640, "from": 308640}, "timestamps": {"to": "00:05:11,640", "from": "00:05:08,640"}}, {"text": "очень много всего, но такого нигде нет.", "offsets": {"to": 314040, "from": 311640}, "timestamps": {"to": "00:05:14,040", "from": "00:05:11,640"}}, {"text": "Вот, поэтому это можно использовать для общего развития,", "offsets": {"to": 318680, "from": 314040}, "timestamps": {"to": "00:05:18,680", "from": "00:05:14,040"}}, {"text": "для понимания, для работы, для собесов,", "offsets": {"to": 320760, "from": 318680}, "timestamps": {"to": "00:05:20,760", "from": "00:05:18,680"}}, {"text": "это в целом, даже потом на собес пойдёте,", "offsets": {"to": 324640, "from": 320760}, "timestamps": {"to": "00:05:24,640", "from": "00:05:20,760"}}, {"text": "вы быстро промотаете и вспомните всё,", "offsets": {"to": 326540, "from": 324640}, "timestamps": {"to": "00:05:26,540", "from": "00:05:24,640"}}, {"text": "и быстренько разжуёте там интервью,", "offsets": {"to": 330840, "from": 326540}, "timestamps": {"to": "00:05:30,840", "from": "00:05:26,540"}}, {"text": "что есть разные скил, аномалии есть разные,", "offsets": {"to": 334220, "from": 331000}, "timestamps": {"to": "00:05:34,220", "from": "00:05:31,000"}}, {"text": "когда чего употреблять,", "offsets": {"to": 335420, "from": 334220}, "timestamps": {"to": "00:05:35,420", "from": "00:05:34,220"}}, {"text": "пессимистик, оптимистик, бла-бла-бла,", "offsets": {"to": 337480, "from": 335420}, "timestamps": {"to": "00:05:37,480", "from": "00:05:35,420"}}, {"text": "и они будут в шоке просто.", "offsets": {"to": 339140, "from": 337480}, "timestamps": {"to": "00:05:39,140", "from": "00:05:37,480"}}, {"text": "Вот, на этом всё, всем пока и хорошего вечера.", "offsets": {"to": 344120, "from": 339140}, "timestamps": {"to": "00:05:44,120", "from": "00:05:39,140"}}]}',NULL,NULL),
	 ('1d963fc3-3dad-4261-abc3-b43df61b0c42','18. Repeatable Read.mp3','SQL_ISOLATIONS','2026-04-10 12:13:00.508',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Repeatable read. Repeatable read, по сути, меняет наше поведение, и теперь мы можем видеть данные, но только те, которые были закомичены, зафиксированы в базе всеми транзакциями на момент чтения, ну, начала текущей транзакции.", "offsets": {"to": 18240, "from": 0}, "timestamps": {"to": "00:00:18,240", "from": "00:00:00,000"}}, {"text": "Мы начали текущую транзакцию, мы, грубо говоря, зафиксировали все данные, которые мы там читаем. Все, что потом будет меняться параллельно, мы видеть не будем.", "offsets": {"to": 29320, "from": 18240}, "timestamps": {"to": "00:00:29,320", "from": "00:00:18,240"}}, {"text": "Мы не видим больше этого. Параллельно меняется, мы не видим. Мы заново читаем данные, и они все время одни и те же. Это repeatable read.", "offsets": {"to": 39780, "from": 30000}, "timestamps": {"to": "00:00:39,780", "from": "00:00:30,000"}}, {"text": "То есть, там что-то меняет параллельные транзакции, удаляет, обновляет, нам пофигу вообще. Мы не видим этого ничего.", "offsets": {"to": 46500, "from": 39780}, "timestamps": {"to": "00:00:46,500", "from": "00:00:39,780"}}, {"text": "Мы просто дальше работаем, как будто ничего не поменялось. И база данных, когда мы попытаемся потом закоммитить, например, сохранить изменения,", "offsets": {"to": 55280, "from": 46500}, "timestamps": {"to": "00:00:55,280", "from": "00:00:46,500"}}, {"text": "нам скажут, что там параллельно что-то понаделали, и все, что ты сейчас сделал, скорее всего, уже не валидно.", "offsets": {"to": 60440, "from": 55280}, "timestamps": {"to": "00:01:00,440", "from": "00:00:55,280"}}, {"text": "Сделай по новой, пожалуйста.", "offsets": {"to": 61600, "from": 60440}, "timestamps": {"to": "00:01:01,600", "from": "00:01:00,440"}}, {"text": "И там уже проверь все по новой и повтори, короче, всю транзакцию по новой.", "offsets": {"to": 67880, "from": 61600}, "timestamps": {"to": "00:01:07,880", "from": "00:01:01,600"}}, {"text": "Данная транзакция в Postgres''е также...", "offsets": {"to": 72740, "from": 68620}, "timestamps": {"to": "00:01:12,740", "from": "00:01:08,620"}}, {"text": "Что я тут написал?", "offsets": {"to": 75080, "from": 72740}, "timestamps": {"to": "00:01:15,080", "from": "00:01:12,740"}}, {"text": "Я как-то странно написал.", "offsets": {"to": 78300, "from": 75080}, "timestamps": {"to": "00:01:18,300", "from": "00:01:15,080"}}, {"text": "Очень странно написал.", "offsets": {"to": 80360, "from": 78300}, "timestamps": {"to": "00:01:20,360", "from": "00:01:18,300"}}, {"text": "А, все.", "offsets": {"to": 81060, "from": 80360}, "timestamps": {"to": "00:01:21,060", "from": "00:01:20,360"}}, {"text": "Короче, я написал, что в Postgres''е она также защищает от фантомного чтения аномалий.", "offsets": {"to": 86840, "from": 81060}, "timestamps": {"to": "00:01:26,840", "from": "00:01:21,060"}}, {"text": "Фантом anomalies.", "offsets": {"to": 88320, "from": 86840}, "timestamps": {"to": "00:01:28,320", "from": "00:01:26,840"}}, {"text": "То есть, если мы просто читаем те же строки заново из базы, с тем же кондишеном мы делаем select,", "offsets": {"to": 97620, "from": 88320}, "timestamps": {"to": "00:01:37,620", "from": "00:01:28,320"}}, {"text": "много строк или одну строку, она возвращается то же самое в текущей транзакции.", "offsets": {"to": 103480, "from": 97620}, "timestamps": {"to": "00:01:43,480", "from": "00:01:37,620"}}, {"text": "И если мы удаляем или добавляем какие-то строки в эту же табличку, то она их тоже не видит.", "offsets": {"to": 109680, "from": 103480}, "timestamps": {"to": "00:01:49,680", "from": "00:01:43,480"}}, {"text": "То есть, все вот эти похожие моменты, они же похожи по сути.", "offsets": {"to": 113700, "from": 109680}, "timestamps": {"to": "00:01:53,700", "from": "00:01:49,680"}}, {"text": "Мы хотим консистентный вид получить одно и то же постоянно.", "offsets": {"to": 117280, "from": 113700}, "timestamps": {"to": "00:01:57,280", "from": "00:01:53,700"}}, {"text": "И фантомы мы тоже не хотим.", "offsets": {"to": 119080, "from": 117280}, "timestamps": {"to": "00:01:59,080", "from": "00:01:57,280"}}, {"text": "Мы вот только что разобрали.", "offsets": {"to": 120300, "from": 119080}, "timestamps": {"to": "00:02:00,300", "from": "00:01:59,080"}}, {"text": "Напоминаю, это новые какие-то строки, которые мы раз и добавили, или наоборот удалили.", "offsets": {"to": 126140, "from": 120300}, "timestamps": {"to": "00:02:06,140", "from": "00:02:00,300"}}, {"text": "Мы заново читаем, а там удалено.", "offsets": {"to": 128280, "from": 126140}, "timestamps": {"to": "00:02:08,280", "from": "00:02:06,140"}}, {"text": "Или новое что-то, и мы в шоке.", "offsets": {"to": 130180, "from": 128280}, "timestamps": {"to": "00:02:10,180", "from": "00:02:08,280"}}, {"text": "В Repeatable Read такого не будет.", "offsets": {"to": 133480, "from": 130180}, "timestamps": {"to": "00:02:13,480", "from": "00:02:10,180"}}, {"text": "Она всегда одно и то же будет возвращать в Postgres''е.", "offsets": {"to": 137680, "from": 133480}, "timestamps": {"to": "00:02:17,680", "from": "00:02:13,480"}}, {"text": "А вот других она может так не работать, потому что по стандарту фантомные чтения", "offsets": {"to": 143360, "from": 137680}, "timestamps": {"to": "00:02:23,360", "from": "00:02:17,680"}}, {"text": "здесь на вот этом уровне не гарантируются.", "offsets": {"to": 145880, "from": 143360}, "timestamps": {"to": "00:02:25,880", "from": "00:02:23,360"}}, {"text": "Но Postgres может это делать, потому что, ну, типа мы можем усиливать их.", "offsets": {"to": 150920, "from": 145880}, "timestamps": {"to": "00:02:30,920", "from": "00:02:25,880"}}, {"text": "Ухудшать не можем, а усиливать текущую транзакцию из уровня изоляции можем.", "offsets": {"to": 156160, "from": 150920}, "timestamps": {"to": "00:02:36,160", "from": "00:02:30,920"}}, {"text": "А в Postgres''е он имплементирован через Snapshot Isolation.", "offsets": {"to": 161240, "from": 156160}, "timestamps": {"to": "00:02:41,240", "from": "00:02:36,160"}}, {"text": "Сериал просто Snapshot Isolation SI.", "offsets": {"to": 165700, "from": 161240}, "timestamps": {"to": "00:02:45,700", "from": "00:02:41,240"}}, {"text": "С помощью Optimistic Locking механизм, который мы тоже разберем потом.", "offsets": {"to": 170140, "from": 165900}, "timestamps": {"to": "00:02:50,140", "from": "00:02:45,900"}}, {"text": "Здесь немножко мы в этом видео про него поговорим.", "offsets": {"to": 172700, "from": 170140}, "timestamps": {"to": "00:02:52,700", "from": "00:02:50,140"}}, {"text": "А более подробно с примерами в другом теоретическом видео разберем.", "offsets": {"to": 177680, "from": 172700}, "timestamps": {"to": "00:02:57,680", "from": "00:02:52,700"}}, {"text": "И может быть практическом.", "offsets": {"to": 178740, "from": 177680}, "timestamps": {"to": "00:02:58,740", "from": "00:02:57,680"}}, {"text": "Вот.", "offsets": {"to": 179900, "from": 178740}, "timestamps": {"to": "00:02:59,900", "from": "00:02:58,740"}}, {"text": "Есть специальный механизм, который называется MVCC, Multiversion Concurrency Control.", "offsets": {"to": 185420, "from": 180120}, "timestamps": {"to": "00:03:05,420", "from": "00:03:00,120"}}, {"text": "Вот.", "offsets": {"to": 186820, "from": 185420}, "timestamps": {"to": "00:03:06,820", "from": "00:03:05,420"}}, {"text": "Он как раз на каждую запись, на каждые вот эти операции, на каждые рекорды, строки,", "offsets": {"to": 193620, "from": 186820}, "timestamps": {"to": "00:03:13,620", "from": "00:03:06,820"}}, {"text": "ставит какие-то определенные версии.", "offsets": {"to": 195460, "from": 193620}, "timestamps": {"to": "00:03:15,460", "from": "00:03:13,620"}}, {"text": "Какой транзакции эти строки принадлежат, какую версию они там имеют и так далее.", "offsets": {"to": 200020, "from": 195460}, "timestamps": {"to": "00:03:20,020", "from": "00:03:15,460"}}, {"text": "Чтобы мы понимали, что если мы заново читаем, мы считаем ровно только то,", "offsets": {"to": 204040, "from": 200020}, "timestamps": {"to": "00:03:24,040", "from": "00:03:20,020"}}, {"text": "что есть у текущей транзакции, а не там все эти строки скопироваться, грубо говоря.", "offsets": {"to": 208540, "from": 204140}, "timestamps": {"to": "00:03:28,540", "from": "00:03:24,140"}}, {"text": "И текущая транзакция только их и будет видеть.", "offsets": {"to": 211140, "from": 208540}, "timestamps": {"to": "00:03:31,140", "from": "00:03:28,540"}}, {"text": "То есть мы будем из этой таблицы читать, грубо говоря, только те записи,", "offsets": {"to": 215960, "from": 211140}, "timestamps": {"to": "00:03:35,960", "from": "00:03:31,140"}}, {"text": "и индекс которых равен, ну или ID которых равен ID нашей транзакции.", "offsets": {"to": 222020, "from": 215960}, "timestamps": {"to": "00:03:42,020", "from": "00:03:35,960"}}, {"text": "Он будет всегда один и тот же.", "offsets": {"to": 223320, "from": 222020}, "timestamps": {"to": "00:03:43,320", "from": "00:03:42,020"}}, {"text": "Мы их там можем в реальности удалять или что-то с ними делать,", "offsets": {"to": 227140, "from": 223320}, "timestamps": {"to": "00:03:47,140", "from": "00:03:43,320"}}, {"text": "но строки, принадлежащие текущей транзакции, они будут неизменны,", "offsets": {"to": 231980, "from": 227140}, "timestamps": {"to": "00:03:51,980", "from": "00:03:47,140"}}, {"text": "и мы будем постоянно одно и то же получать.", "offsets": {"to": 233620, "from": 231980}, "timestamps": {"to": "00:03:53,620", "from": "00:03:51,980"}}, {"text": "Ну а текущая repeatable read, она не защищает от serialization anomalies.", "offsets": {"to": 241640, "from": 233620}, "timestamps": {"to": "00:04:01,640", "from": "00:03:53,620"}}, {"text": "То есть вот эти вот сериализации, которые мы разобрали,", "offsets": {"to": 244600, "from": 241640}, "timestamps": {"to": "00:04:04,600", "from": "00:04:01,640"}}, {"text": "с write-sq0, write-sq1, 2, read-sq с докторами, циклическая и другие,", "offsets": {"to": 253900, "from": 244600}, "timestamps": {"to": "00:04:13,900", "from": "00:04:04,600"}}, {"text": "можете отмотать назад, посмотреть, вот она уже не защищает,", "offsets": {"to": 257480, "from": 253900}, "timestamps": {"to": "00:04:17,480", "from": "00:04:13,900"}}, {"text": "она не видит их, она не понимает.", "offsets": {"to": 258980, "from": 257480}, "timestamps": {"to": "00:04:18,980", "from": "00:04:17,480"}}, {"text": "И эти аномалии могут случаться и приводить к тому результату,", "offsets": {"to": 266000, "from": 259980}, "timestamps": {"to": "00:04:26,000", "from": "00:04:19,980"}}, {"text": "который мы не ожидаем.", "offsets": {"to": 267060, "from": 266000}, "timestamps": {"to": "00:04:27,060", "from": "00:04:26,000"}}, {"text": "Эта анататура не видит ее.", "offsets": {"to": 269800, "from": 267060}, "timestamps": {"to": "00:04:29,800", "from": "00:04:27,060"}}, {"text": "Для этого, чтобы видеть, был разработан,", "offsets": {"to": 273420, "from": 269800}, "timestamps": {"to": "00:04:33,420", "from": "00:04:29,800"}}, {"text": "ну, есть локирующие алгоритмы,", "offsets": {"to": 276760, "from": 273420}, "timestamps": {"to": "00:04:36,760", "from": "00:04:33,420"}}, {"text": "как называется, two-step lock, этот locking алгоритм,", "offsets": {"to": 282980, "from": 276760}, "timestamps": {"to": "00:04:42,980", "from": "00:04:36,760"}}, {"text": "и второе, который использует Postgres, я тоже позже про него скажу,", "offsets": {"to": 289360, "from": 283140}, "timestamps": {"to": "00:04:49,360", "from": "00:04:43,140"}}, {"text": "serializable snapshot isolation, который устроен как раз тоже на контроле версии,", "offsets": {"to": 297860, "from": 289360}, "timestamps": {"to": "00:04:57,860", "from": "00:04:49,360"}}, {"text": "на специальных графах, которые могут отслеживать,", "offsets": {"to": 300880, "from": 297860}, "timestamps": {"to": "00:05:00,880", "from": "00:04:57,860"}}, {"text": "строить прям графы, которые отслеживают текущее состояние и взаимосвязи,", "offsets": {"to": 305540, "from": 300880}, "timestamps": {"to": "00:05:05,540", "from": "00:05:00,880"}}, {"text": "циклы находить, что несколько транзакций,", "offsets": {"to": 308800, "from": 305540}, "timestamps": {"to": "00:05:08,800", "from": "00:05:05,540"}}, {"text": "вырезают одни и те же данные, на основе них там что-то происходит.", "offsets": {"to": 311980, "from": 308900}, "timestamps": {"to": "00:05:11,980", "from": "00:05:08,900"}}, {"text": "И она предполагает, что, скорее всего, так делать нельзя,", "offsets": {"to": 314960, "from": 311980}, "timestamps": {"to": "00:05:14,960", "from": "00:05:11,980"}}, {"text": "не надо так пересекаться, и может дать отлуп.", "offsets": {"to": 317760, "from": 314960}, "timestamps": {"to": "00:05:17,760", "from": "00:05:14,960"}}, {"text": "Но это накладывает, естественно, некоторые расходы.", "offsets": {"to": 321980, "from": 317760}, "timestamps": {"to": "00:05:21,980", "from": "00:05:17,760"}}, {"text": "Serializable.", "offsets": {"to": 323000, "from": 321980}, "timestamps": {"to": "00:05:23,000", "from": "00:05:21,980"}}]}',NULL,NULL),
	 ('ed8c04f0-bd14-4f1a-86c7-a0b11865802c','17. Read Committed.mp3','SQL_ISOLATIONS','2026-04-10 12:12:35.842',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Рид коммитед – это транзакция, которая защищает нас от грязного чтения, от дёти-рид.", "offsets": {"to": 7220, "from": 0}, "timestamps": {"to": "00:00:07,220", "from": "00:00:00,000"}}, {"text": "То есть мы делаем селект.", "offsets": {"to": 10880, "from": 7220}, "timestamps": {"to": "00:00:10,880", "from": "00:00:07,220"}}, {"text": "Вот я написал селект клаус, да?", "offsets": {"to": 13960, "from": 10880}, "timestamps": {"to": "00:00:13,960", "from": "00:00:10,880"}}, {"text": "We''ll return the latest коммитед вершин.", "offsets": {"to": 15880, "from": 13960}, "timestamps": {"to": "00:00:15,880", "from": "00:00:13,960"}}, {"text": "То есть наш селект, он будет возвращать самую последнюю версию данных,", "offsets": {"to": 23440, "from": 15880}, "timestamps": {"to": "00:00:23,440", "from": "00:00:15,880"}}, {"text": "которые были закомичены.", "offsets": {"to": 25920, "from": 23440}, "timestamps": {"to": "00:00:25,920", "from": "00:00:23,440"}}, {"text": "Если они были не закомичены, дёти-рид, то нам они не вернутся.", "offsets": {"to": 31360, "from": 25920}, "timestamps": {"to": "00:00:31,360", "from": "00:00:25,920"}}, {"text": "Только зафиксированные.", "offsets": {"to": 32780, "from": 31360}, "timestamps": {"to": "00:00:32,780", "from": "00:00:31,360"}}, {"text": "Таким образом, оно по сути возвращает нам снапшот наших данных.", "offsets": {"to": 40620, "from": 32780}, "timestamps": {"to": "00:00:40,620", "from": "00:00:32,780"}}, {"text": "То есть она не лочит нам ничего, это не лочка.", "offsets": {"to": 44560, "from": 40620}, "timestamps": {"to": "00:00:44,560", "from": "00:00:40,620"}}, {"text": "Она не блокирует полностью наши данные, не дает кому-то читать.", "offsets": {"to": 50420, "from": 44560}, "timestamps": {"to": "00:00:50,420", "from": "00:00:44,560"}}, {"text": "Это не так.", "offsets": {"to": 51000, "from": 50420}, "timestamps": {"to": "00:00:51,000", "from": "00:00:50,420"}}, {"text": "Она просто берет и текущую версию закомиченную читает.", "offsets": {"to": 54580, "from": 51000}, "timestamps": {"to": "00:00:54,580", "from": "00:00:51,000"}}, {"text": "Если эта версия будет изменена, параллельной транзакцией, да,", "offsets": {"to": 58740, "from": 54580}, "timestamps": {"to": "00:00:58,740", "from": "00:00:54,580"}}, {"text": "будет какой-то апдейт под новую версию,", "offsets": {"to": 62220, "from": 58740}, "timestamps": {"to": "00:01:02,220", "from": "00:00:58,740"}}, {"text": "то мы можем заново читать уже другую закомиченную версию.", "offsets": {"to": 65380, "from": 62220}, "timestamps": {"to": "00:01:05,380", "from": "00:01:02,220"}}, {"text": "То есть мы читаем текущий снапшот постоянно.", "offsets": {"to": 67620, "from": 65380}, "timestamps": {"to": "00:01:07,620", "from": "00:01:05,380"}}, {"text": "Вот.", "offsets": {"to": 68960, "from": 67620}, "timestamps": {"to": "00:01:08,960", "from": "00:01:07,620"}}, {"text": "Лочки не гарантируются.", "offsets": {"to": 71440, "from": 68960}, "timestamps": {"to": "00:01:11,440", "from": "00:01:08,960"}}, {"text": "Рейндж лочки тоже не гарантируют.", "offsets": {"to": 73860, "from": 71440}, "timestamps": {"to": "00:01:13,860", "from": "00:01:11,440"}}, {"text": "Просто текущую версию читаем, и всё.", "offsets": {"to": 75860, "from": 73860}, "timestamps": {"to": "00:01:15,860", "from": "00:01:13,860"}}, {"text": "Я вот написал рекорд, да, записи.", "offsets": {"to": 79180, "from": 75860}, "timestamps": {"to": "00:01:19,180", "from": "00:01:15,860"}}, {"text": "Они могут быть потом, после нашего чтения, обновлены, апдейтед, удалены, делитед, новые добавлены.", "offsets": {"to": 86380, "from": 79180}, "timestamps": {"to": "00:01:26,380", "from": "00:01:19,180"}}, {"text": "Могут быть заблокированы как-то другой транзакцией.", "offsets": {"to": 89140, "from": 86380}, "timestamps": {"to": "00:01:29,140", "from": "00:01:26,380"}}, {"text": "Ну, то есть разные могут быть после этого какие-то операции над этими данными.", "offsets": {"to": 94200, "from": 89140}, "timestamps": {"to": "00:01:34,200", "from": "00:01:29,140"}}, {"text": "Эта транзакция является стандартной в подгрессе, и она довольно быстрая.", "offsets": {"to": 101520, "from": 95140}, "timestamps": {"to": "00:01:41,520", "from": "00:01:35,140"}}, {"text": "Самая оптимальная транзакция, уровень её, она быстрая и достаточно надёжная.", "offsets": {"to": 106300, "from": 101520}, "timestamps": {"to": "00:01:46,300", "from": "00:01:41,520"}}, {"text": "То есть у нас нет грязного чтения дьюти-рит, и мы можем довольно изолированно работать.", "offsets": {"to": 113400, "from": 106300}, "timestamps": {"to": "00:01:53,400", "from": "00:01:46,300"}}, {"text": "Если нам не надо несколько раз читать, мы читали данные, на основе них что-то делаем.", "offsets": {"to": 117360, "from": 113400}, "timestamps": {"to": "00:01:57,360", "from": "00:01:53,400"}}, {"text": "То есть если у нас нет каких-то, вот я написал комплекс queries, да, или апдейтов, то всё будет хорошо.", "offsets": {"to": 125640, "from": 118620}, "timestamps": {"to": "00:02:05,640", "from": "00:01:58,620"}}, {"text": "И многие другие вещи мы можем тоже обезопасить, имея read-committed с помощью лочек разного вида и так далее.", "offsets": {"to": 134700, "from": 125640}, "timestamps": {"to": "00:02:14,700", "from": "00:02:05,640"}}, {"text": "Об этом мы будем говорить через одно видео.", "offsets": {"to": 137260, "from": 134700}, "timestamps": {"to": "00:02:17,260", "from": "00:02:14,700"}}, {"text": "в теоретическом и тоже будет практическое, наверное, или только теоретическое,", "offsets": {"to": 141580, "from": 137920}, "timestamps": {"to": "00:02:21,580", "from": "00:02:17,920"}}, {"text": "про то, как это всё использовать, когда оно приводит к плохим результатам,", "offsets": {"to": 146740, "from": 141580}, "timestamps": {"to": "00:02:26,740", "from": "00:02:21,580"}}, {"text": "и как нам это обезопасить, какие лочки использовать там и так далее.", "offsets": {"to": 149700, "from": 146740}, "timestamps": {"to": "00:02:29,700", "from": "00:02:26,740"}}, {"text": "Тоже интересная тема.", "offsets": {"to": 151800, "from": 149700}, "timestamps": {"to": "00:02:31,800", "from": "00:02:29,700"}}]}',NULL,NULL);
INSERT INTO public."transcription" (id,"name",code,"created_at","order",tags,"content","section","transcription_text") VALUES
	 ('e0ac2a3d-d440-4279-826a-b5b4dfb82af0','01. ACID (АСИД).mp3','SQL_ISOLATIONS','2026-04-10 12:06:57.265',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "И мы помним, что в ACID есть isolation, то есть ACID это то, что это atomicity, consistency, isolation, durability. И вот isolation как раз это уровень изоляции транзакций, как они изолируются, isolate.", "offsets": {"to": 18360, "from": 0}, "timestamps": {"to": "00:00:18,360", "from": "00:00:00,000"}}, {"text": "Вот, то есть если выполняются у нас две параллельных транзакции, какие изменения у первой транзакции, что она вообще делает, видит вторая транзакция и вообще видит ли она что-нибудь, или она вообще ничего не видит, тут барьер стоит и все, она вообще ничего не понимает.", "offsets": {"to": 34880, "from": 19260}, "timestamps": {"to": "00:00:34,880", "from": "00:00:19,260"}}, {"text": "И для этого как раз были сделаны разные уровни, потому что какие-то уровни дают нам больше перформанса, какие-то больше консистентности, надежности дают, reliability какого-то.", "offsets": {"to": 48980, "from": 35140}, "timestamps": {"to": "00:00:48,980", "from": "00:00:35,140"}}, {"text": "И получается, мы должны выбрать, какой нам нужен, какой уровень мы хотим использовать.", "offsets": {"to": 55480, "from": 48980}, "timestamps": {"to": "00:00:55,480", "from": "00:00:48,980"}}, {"text": "И непонятно, да, какой, чем они вообще отличаются и почему, например, не использовать самый классный какой-нибудь, самый крутой, да, который вообще все делает типа за нас.", "offsets": {"to": 65060, "from": 55480}, "timestamps": {"to": "00:01:05,060", "from": "00:00:55,480"}}, {"text": "Но я потом покажу, что даже самый высший уровень изоляции не может справиться с некоторыми проблемами, которые приводят к коллизиям или аномалиям.", "offsets": {"to": 74820, "from": 65060}, "timestamps": {"to": "00:01:14,820", "from": "00:01:05,060"}}, {"text": "И он не может это отработать.", "offsets": {"to": 76820, "from": 74820}, "timestamps": {"to": "00:01:16,820", "from": "00:01:14,820"}}, {"text": "Вот, скорее всего, это будет в практическом задаче.", "offsets": {"to": 79400, "from": 76820}, "timestamps": {"to": "00:01:19,400", "from": "00:01:16,820"}}, {"text": "Тьфу, видео, я уже материал подготовил, осталось вот снять, будет потом, как у меня время появится.", "offsets": {"to": 87000, "from": 79400}, "timestamps": {"to": "00:01:27,000", "from": "00:01:19,400"}}, {"text": "Вот, то есть не всегда работа с повышением, понижением транзакции может вообще решить проблему транзакции.", "offsets": {"to": 97980, "from": 87000}, "timestamps": {"to": "00:01:37,980", "from": "00:01:27,000"}}]}',NULL,'И мы помним, что в ACID есть isolation, то есть ACID это то, что это atomicity, consistency, isolation, durability. И вот isolation как раз это уровень изоляции транзакций, как они изолируются, isolate. Вот, то есть если выполняются у нас две параллельных транзакции, какие изменения у первой транзакции, что она вообще делает, видит вторая транзакция и вообще видит ли она что-нибудь, или она вообще ничего не видит, тут барьер стоит и все, она вообще ничего не понимает. И для этого как раз были сделаны разные уровни, потому что какие-то уровни дают нам больше перформанса, какие-то больше консистентности, надежности дают, reliability какого-то. И получается, мы должны выбрать, какой нам нужен, какой уровень мы хотим использовать. И непонятно, да, какой, чем они вообще отличаются и почему, например, не использовать самый классный какой-нибудь, самый крутой, да, который вообще все делает типа за нас. Но я потом покажу, что даже самый высший уровень изоляции не может справиться с некоторыми проблемами, которые приводят к коллизиям или аномалиям. И он не может это отработать. Вот, скорее всего, это будет в практическом задаче. Тьфу, видео, я уже материал подготовил, осталось вот снять, будет потом, как у меня время появится. Вот, то есть не всегда работа с повышением, понижением транзакции может вообще решить проблему транзакции.'),
	 ('19ba9d2d-75cf-4d0d-a66d-5c0414882abb','02. Transaction (Транзакция).mp3','SQL_ISOLATIONS','2026-04-10 12:07:08.108',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Что это такое?", "offsets": {"to": 820, "from": 0}, "timestamps": {"to": "00:00:00,820", "from": "00:00:00,000"}}, {"text": "Транзакция – это некоторые single unit of work,", "offsets": {"to": 4120, "from": 820}, "timestamps": {"to": "00:00:04,120", "from": "00:00:00,820"}}, {"text": "то есть это набор какой-то совокупных операций,", "offsets": {"to": 8020, "from": 4120}, "timestamps": {"to": "00:00:08,020", "from": "00:00:04,120"}}, {"text": "которые мы рассматриваем как атомарную одну.", "offsets": {"to": 10200, "from": 8020}, "timestamps": {"to": "00:00:10,200", "from": "00:00:08,020"}}, {"text": "То есть либо все эти операции вместе выполняются,", "offsets": {"to": 13300, "from": 10200}, "timestamps": {"to": "00:00:13,300", "from": "00:00:10,200"}}, {"text": "либо вообще никакая не выполняется.", "offsets": {"to": 15120, "from": 13300}, "timestamps": {"to": "00:00:15,120", "from": "00:00:13,300"}}, {"text": "Если все хорошо, мы применили множество операций,", "offsets": {"to": 18900, "from": 15120}, "timestamps": {"to": "00:00:18,900", "from": "00:00:15,120"}}, {"text": "мы говорим, ну вроде все хорошо по логике нашей, да,", "offsets": {"to": 21600, "from": 18900}, "timestamps": {"to": "00:00:21,600", "from": "00:00:18,900"}}, {"text": "и база данных говорит, что все наши изменения,", "offsets": {"to": 25540, "from": 21600}, "timestamps": {"to": "00:00:25,540", "from": "00:00:21,600"}}, {"text": "они валидные, они подходят под все констранции,", "offsets": {"to": 29020, "from": 25540}, "timestamps": {"to": "00:00:29,020", "from": "00:00:25,540"}}, {"text": "которые мы задали.", "offsets": {"to": 29900, "from": 29020}, "timestamps": {"to": "00:00:29,900", "from": "00:00:29,020"}}, {"text": "Там unique, franky, primary key, какие-нибудь диапазоны,", "offsets": {"to": 36180, "from": 30380}, "timestamps": {"to": "00:00:36,180", "from": "00:00:30,380"}}, {"text": "значения и прочее, все хорошо.", "offsets": {"to": 38560, "from": 36180}, "timestamps": {"to": "00:00:38,560", "from": "00:00:36,180"}}, {"text": "Мы говорим commit, и все эти изменения,", "offsets": {"to": 41800, "from": 38560}, "timestamps": {"to": "00:00:41,800", "from": "00:00:38,560"}}, {"text": "они сохраняются в базу данных.", "offsets": {"to": 43520, "from": 41800}, "timestamps": {"to": "00:00:43,520", "from": "00:00:41,800"}}, {"text": "Мы уже говорили в прошлом, видите, durability, да,", "offsets": {"to": 45860, "from": 43520}, "timestamps": {"to": "00:00:45,860", "from": "00:00:43,520"}}, {"text": "они сохранились, и все, они вечно там.", "offsets": {"to": 49000, "from": 45860}, "timestamps": {"to": "00:00:49,000", "from": "00:00:45,860"}}, {"text": "Мы их всегда сможем обратно прочитать.", "offsets": {"to": 53000, "from": 49000}, "timestamps": {"to": "00:00:53,000", "from": "00:00:49,000"}}, {"text": "Если какая-то проблема, то мы делаем rollback,", "offsets": {"to": 56060, "from": 53000}, "timestamps": {"to": "00:00:56,060", "from": "00:00:53,000"}}, {"text": "и все, что мы делали, отменяется.", "offsets": {"to": 57640, "from": 56060}, "timestamps": {"to": "00:00:57,640", "from": "00:00:56,060"}}, {"text": "Вот и нарисовал этот рисуночек.", "offsets": {"to": 59120, "from": 57640}, "timestamps": {"to": "00:00:59,120", "from": "00:00:57,640"}}, {"text": "Вот это вот наша транзакция, прямоугольник синий.", "offsets": {"to": 62860, "from": 59160}, "timestamps": {"to": "00:01:02,860", "from": "00:00:59,160"}}, {"text": "Она работает над некоторыми данными,", "offsets": {"to": 66400, "from": 62860}, "timestamps": {"to": "00:01:06,400", "from": "00:01:02,860"}}, {"text": "которые обозначены вот такими маленькими квадратиками.", "offsets": {"to": 69240, "from": 66400}, "timestamps": {"to": "00:01:09,240", "from": "00:01:06,400"}}, {"text": "В какой-то момент времени мы меняем эти данные,", "offsets": {"to": 73000, "from": 69240}, "timestamps": {"to": "00:01:13,000", "from": "00:01:09,240"}}, {"text": "и они вот становятся поменены и зелененькие.", "offsets": {"to": 76300, "from": 73000}, "timestamps": {"to": "00:01:16,300", "from": "00:01:13,000"}}, {"text": "И транзакция меняет свой стейт.", "offsets": {"to": 78400, "from": 76300}, "timestamps": {"to": "00:01:18,400", "from": "00:01:16,300"}}, {"text": "Теперь мы знаем, что в этой транзакции она стала зеленая,", "offsets": {"to": 81320, "from": 78400}, "timestamps": {"to": "00:01:21,320", "from": "00:01:18,400"}}, {"text": "что-то было изменено.", "offsets": {"to": 82440, "from": 81320}, "timestamps": {"to": "00:01:22,440", "from": "00:01:21,320"}}, {"text": "То есть, там есть какие-то изменения, которые нам потом зафиксировать надо,", "offsets": {"to": 87420, "from": 82520}, "timestamps": {"to": "00:01:27,420", "from": "00:01:22,520"}}, {"text": "либо откатить.", "offsets": {"to": 88180, "from": 87420}, "timestamps": {"to": "00:01:28,180", "from": "00:01:27,420"}}, {"text": "В какой-то момент времени мы понимаем, что мы сломали наши данные,", "offsets": {"to": 92700, "from": 88180}, "timestamps": {"to": "00:01:32,700", "from": "00:01:28,180"}}, {"text": "что-то произошло не так.", "offsets": {"to": 93920, "from": 92700}, "timestamps": {"to": "00:01:33,920", "from": "00:01:32,700"}}, {"text": "Либо логика какая-то, ошибка в программе,", "offsets": {"to": 96100, "from": 93920}, "timestamps": {"to": "00:01:36,100", "from": "00:01:33,920"}}, {"text": "либо, может быть, мы испортили данные,", "offsets": {"to": 98380, "from": 96100}, "timestamps": {"to": "00:01:38,380", "from": "00:01:36,100"}}, {"text": "база среагировала, да, на конструенции.", "offsets": {"to": 100440, "from": 98380}, "timestamps": {"to": "00:01:40,440", "from": "00:01:38,380"}}, {"text": "И либо база сама, либо мы говорим,", "offsets": {"to": 104000, "from": 100440}, "timestamps": {"to": "00:01:44,000", "from": "00:01:40,440"}}, {"text": "все, мы так не хотим, какая-то проблема,", "offsets": {"to": 106000, "from": 104000}, "timestamps": {"to": "00:01:46,000", "from": "00:01:44,000"}}, {"text": "мы хотим просто сделать роллбэк и вернуть,", "offsets": {"to": 108860, "from": 106140}, "timestamps": {"to": "00:01:48,860", "from": "00:01:46,140"}}, {"text": "вот видите, все в ровно то состояние,", "offsets": {"to": 111120, "from": 108860}, "timestamps": {"to": "00:01:51,120", "from": "00:01:48,860"}}, {"text": "которое было в самом начале, в beginning, да.", "offsets": {"to": 113800, "from": 111120}, "timestamps": {"to": "00:01:53,800", "from": "00:01:51,120"}}, {"text": "А вот, то есть, мы откатываем абсолютно все изменения,", "offsets": {"to": 117800, "from": 113800}, "timestamps": {"to": "00:01:57,800", "from": "00:01:53,800"}}, {"text": "которые вот мы тут производили, и плохие, и хорошие.", "offsets": {"to": 120880, "from": 117800}, "timestamps": {"to": "00:02:00,880", "from": "00:01:57,800"}}, {"text": "Вот, хотим откатить, если все плохо.", "offsets": {"to": 123940, "from": 120880}, "timestamps": {"to": "00:02:03,940", "from": "00:02:00,880"}}, {"text": "Если все хорошо, мы нажмем применить, коммит,", "offsets": {"to": 127480, "from": 123940}, "timestamps": {"to": "00:02:07,480", "from": "00:02:03,940"}}, {"text": "и вот эти все наши изменения сохранятся.", "offsets": {"to": 129920, "from": 127480}, "timestamps": {"to": "00:02:09,920", "from": "00:02:07,480"}}, {"text": "Это что такое транзакция?", "offsets": {"to": 132420, "from": 129920}, "timestamps": {"to": "00:02:12,420", "from": "00:02:09,920"}}]}',NULL,'Что это такое? Транзакция – это некоторые single unit of work, то есть это набор какой-то совокупных операций, которые мы рассматриваем как атомарную одну. То есть либо все эти операции вместе выполняются, либо вообще никакая не выполняется. Если все хорошо, мы применили множество операций, мы говорим, ну вроде все хорошо по логике нашей, да, и база данных говорит, что все наши изменения, они валидные, они подходят под все констранции, которые мы задали. Там unique, franky, primary key, какие-нибудь диапазоны, значения и прочее, все хорошо. Мы говорим commit, и все эти изменения, они сохраняются в базу данных. Мы уже говорили в прошлом, видите, durability, да, они сохранились, и все, они вечно там. Мы их всегда сможем обратно прочитать. Если какая-то проблема, то мы делаем rollback, и все, что мы делали, отменяется. Вот и нарисовал этот рисуночек. Вот это вот наша транзакция, прямоугольник синий. Она работает над некоторыми данными, которые обозначены вот такими маленькими квадратиками. В какой-то момент времени мы меняем эти данные, и они вот становятся поменены и зелененькие. И транзакция меняет свой стейт. Теперь мы знаем, что в этой транзакции она стала зеленая, что-то было изменено. То есть, там есть какие-то изменения, которые нам потом зафиксировать надо, либо откатить. В какой-то момент времени мы понимаем, что мы сломали наши данные, что-то произошло не так. Либо логика какая-то, ошибка в программе, либо, может быть, мы испортили данные, база среагировала, да, на конструенции. И либо база сама, либо мы говорим, все, мы так не хотим, какая-то проблема, мы хотим просто сделать роллбэк и вернуть, вот видите, все в ровно то состояние, которое было в самом начале, в beginning, да. А вот, то есть, мы откатываем абсолютно все изменения, которые вот мы тут производили, и плохие, и хорошие. Вот, хотим откатить, если все плохо. Если все хорошо, мы нажмем применить, коммит, и вот эти все наши изменения сохранятся. Это что такое транзакция?'),
	 ('22c4bd7b-c6df-45c6-92c9-807b6102f9b9','03. Isolation (Изоляция).mp3','SQL_ISOLATIONS','2026-04-10 12:07:23.795',0,'{SQL}','{"result": {"language": "ru"}, "transcription": [{"text": "Дальше", "offsets": {"to": 3240, "from": 0}, "timestamps": {"to": "00:00:03,240", "from": "00:00:00,000"}}, {"text": "Isolation", "offsets": {"to": 4820, "from": 3240}, "timestamps": {"to": "00:00:04,820", "from": "00:00:03,240"}}, {"text": "Итак", "offsets": {"to": 6300, "from": 4820}, "timestamps": {"to": "00:00:06,300", "from": "00:00:04,820"}}, {"text": "Изоляция говорит нам о том", "offsets": {"to": 9240, "from": 6300}, "timestamps": {"to": "00:00:09,240", "from": "00:00:06,300"}}, {"text": "Что наши транзакции", "offsets": {"to": 11560, "from": 9240}, "timestamps": {"to": "00:00:11,560", "from": "00:00:09,240"}}, {"text": "Должны каким-то образом быть изолированы", "offsets": {"to": 13480, "from": 11560}, "timestamps": {"to": "00:00:13,480", "from": "00:00:11,560"}}, {"text": "Мы должны выбирать", "offsets": {"to": 14580, "from": 13480}, "timestamps": {"to": "00:00:14,580", "from": "00:00:13,480"}}, {"text": "Что нам важно", "offsets": {"to": 17060, "from": 14580}, "timestamps": {"to": "00:00:17,060", "from": "00:00:14,580"}}, {"text": "На каком уровне мы хотим изолировать", "offsets": {"to": 19540, "from": 17060}, "timestamps": {"to": "00:00:19,540", "from": "00:00:17,060"}}, {"text": "Мы хотим максимальную", "offsets": {"to": 21240, "from": 19540}, "timestamps": {"to": "00:00:21,240", "from": "00:00:19,540"}}, {"text": "Производительность, перформанс", "offsets": {"to": 22680, "from": 21240}, "timestamps": {"to": "00:00:22,680", "from": "00:00:21,240"}}, {"text": "Или максимальную надежность", "offsets": {"to": 24320, "from": 22680}, "timestamps": {"to": "00:00:24,320", "from": "00:00:22,680"}}, {"text": "Railability какой-нибудь", "offsets": {"to": 26740, "from": 24320}, "timestamps": {"to": "00:00:26,740", "from": "00:00:24,320"}}, {"text": "Здесь я нарисовал еще один примерчик", "offsets": {"to": 29740, "from": 26740}, "timestamps": {"to": "00:00:29,740", "from": "00:00:26,740"}}, {"text": "Вот", "offsets": {"to": 31740, "from": 29740}, "timestamps": {"to": "00:00:31,740", "from": "00:00:29,740"}}, {"text": "То есть я тут написал", "offsets": {"to": 34200, "from": 31740}, "timestamps": {"to": "00:00:34,200", "from": "00:00:31,740"}}, {"text": "Это base insurance", "offsets": {"to": 35080, "from": 34200}, "timestamps": {"to": "00:00:35,080", "from": "00:00:34,200"}}, {"text": "Она контролирует, она убеждает", "offsets": {"to": 36960, "from": 35080}, "timestamps": {"to": "00:00:36,960", "from": "00:00:35,080"}}, {"text": "Убеждается сама в том, что", "offsets": {"to": 38800, "from": 36960}, "timestamps": {"to": "00:00:38,800", "from": "00:00:36,960"}}, {"text": "Как вообще транзакции", "offsets": {"to": 41180, "from": 38800}, "timestamps": {"to": "00:00:41,180", "from": "00:00:38,800"}}, {"text": "Аффектят друг друга, влияют друг на друга", "offsets": {"to": 43620, "from": 41180}, "timestamps": {"to": "00:00:43,620", "from": "00:00:41,180"}}, {"text": "Чтобы сохранить", "offsets": {"to": 45260, "from": 43620}, "timestamps": {"to": "00:00:45,260", "from": "00:00:43,620"}}, {"text": "Баздах постоянно беспокоится", "offsets": {"to": 46900, "from": 45260}, "timestamps": {"to": "00:00:46,900", "from": "00:00:45,260"}}, {"text": "О консистентности наших данных", "offsets": {"to": 49040, "from": 46900}, "timestamps": {"to": "00:00:49,040", "from": "00:00:46,900"}}, {"text": "И мы помогаем в этом", "offsets": {"to": 50600, "from": 49040}, "timestamps": {"to": "00:00:50,600", "from": "00:00:49,040"}}, {"text": "Вот, то есть на этой картинке", "offsets": {"to": 53700, "from": 50600}, "timestamps": {"to": "00:00:53,700", "from": "00:00:50,600"}}, {"text": "Я схематически изобразил", "offsets": {"to": 55260, "from": 53700}, "timestamps": {"to": "00:00:55,260", "from": "00:00:53,700"}}, {"text": "Что у нас есть какие-то данные в нашей базе данных", "offsets": {"to": 57900, "from": 55260}, "timestamps": {"to": "00:00:57,900", "from": "00:00:55,260"}}, {"text": "И изоляцию я изобразил", "offsets": {"to": 59480, "from": 57900}, "timestamps": {"to": "00:00:59,480", "from": "00:00:57,900"}}, {"text": "С помощью вот такого вот барьера", "offsets": {"to": 61000, "from": 59480}, "timestamps": {"to": "00:01:01,000", "from": "00:00:59,480"}}, {"text": "Я их делал", "offsets": {"to": 61640, "from": 61000}, "timestamps": {"to": "00:01:01,640", "from": "00:01:01,000"}}, {"text": "Видео по memory modules", "offsets": {"to": 66300, "from": 61640}, "timestamps": {"to": "00:01:06,300", "from": "00:01:01,640"}}, {"text": "Memory consistent modules", "offsets": {"to": 68540, "from": 66300}, "timestamps": {"to": "00:01:08,540", "from": "00:01:06,300"}}, {"text": "Очень похожая тема", "offsets": {"to": 71020, "from": 68540}, "timestamps": {"to": "00:01:11,020", "from": "00:01:08,540"}}, {"text": "Есть какие-то данные", "offsets": {"to": 72120, "from": 71020}, "timestamps": {"to": "00:01:12,120", "from": "00:01:11,020"}}, {"text": "Есть вот одна транзакция", "offsets": {"to": 73700, "from": 72120}, "timestamps": {"to": "00:01:13,700", "from": "00:01:12,120"}}, {"text": "Есть вторая транзакция", "offsets": {"to": 75340, "from": 73700}, "timestamps": {"to": "00:01:15,340", "from": "00:01:13,700"}}, {"text": "И они меняют как-то эти данные", "offsets": {"to": 77160, "from": 75340}, "timestamps": {"to": "00:01:17,160", "from": "00:01:15,340"}}, {"text": "То есть первая транзакция", "offsets": {"to": 79060, "from": 77160}, "timestamps": {"to": "00:01:19,060", "from": "00:01:17,160"}}, {"text": "Поменяла данные", "offsets": {"to": 79940, "from": 79060}, "timestamps": {"to": "00:01:19,940", "from": "00:01:19,060"}}, {"text": "Вот эти, да", "offsets": {"to": 80600, "from": 79940}, "timestamps": {"to": "00:01:20,600", "from": "00:01:19,940"}}, {"text": "Зелененькие", "offsets": {"to": 81880, "from": 80600}, "timestamps": {"to": "00:01:21,880", "from": "00:01:20,600"}}, {"text": "Они стали изменены", "offsets": {"to": 82940, "from": 81880}, "timestamps": {"to": "00:01:22,940", "from": "00:01:21,880"}}, {"text": "Оранжевые", "offsets": {"to": 83700, "from": 82940}, "timestamps": {"to": "00:01:23,700", "from": "00:01:22,940"}}, {"text": "Эта транзакция будет иметь", "offsets": {"to": 85580, "from": 83700}, "timestamps": {"to": "00:01:25,580", "from": "00:01:23,700"}}, {"text": "Свою собственную", "offsets": {"to": 86980, "from": 85580}, "timestamps": {"to": "00:01:26,980", "from": "00:01:25,580"}}, {"text": "Прямо копию этих данных", "offsets": {"to": 88920, "from": 86980}, "timestamps": {"to": "00:01:28,920", "from": "00:01:26,980"}}, {"text": "Postgres, например, может", "offsets": {"to": 91100, "from": 88920}, "timestamps": {"to": "00:01:31,100", "from": "00:01:28,920"}}, {"text": "Копировать прямо вот эти данные", "offsets": {"to": 92820, "from": 91100}, "timestamps": {"to": "00:01:32,820", "from": "00:01:31,100"}}, {"text": "В эту же таблицу", "offsets": {"to": 94140, "from": 92820}, "timestamps": {"to": "00:01:34,140", "from": "00:01:32,820"}}, {"text": "Рядышком", "offsets": {"to": 94840, "from": 94140}, "timestamps": {"to": "00:01:34,840", "from": "00:01:34,140"}}, {"text": "И помещать, что", "offsets": {"to": 96100, "from": 94840}, "timestamps": {"to": "00:01:36,100", "from": "00:01:34,840"}}, {"text": "Этот рекорд", "offsets": {"to": 97720, "from": 96100}, "timestamps": {"to": "00:01:37,720", "from": "00:01:36,100"}}, {"text": "Да", "offsets": {"to": 97960, "from": 97720}, "timestamps": {"to": "00:01:37,960", "from": "00:01:37,720"}}, {"text": "Принадлежит вот этой транзакции", "offsets": {"to": 99820, "from": 97960}, "timestamps": {"to": "00:01:39,820", "from": "00:01:37,960"}}, {"text": "Только ей", "offsets": {"to": 100420, "from": 99820}, "timestamps": {"to": "00:01:40,420", "from": "00:01:39,820"}}, {"text": "Что он находится в ней", "offsets": {"to": 101920, "from": 100420}, "timestamps": {"to": "00:01:41,920", "from": "00:01:40,420"}}, {"text": "Таким образом", "offsets": {"to": 103000, "from": 101920}, "timestamps": {"to": "00:01:43,000", "from": "00:01:41,920"}}, {"text": "База данных", "offsets": {"to": 103980, "from": 103000}, "timestamps": {"to": "00:01:43,980", "from": "00:01:43,000"}}, {"text": "Всегда понимает", "offsets": {"to": 104760, "from": 103980}, "timestamps": {"to": "00:01:44,760", "from": "00:01:43,980"}}, {"text": "Какие значения", "offsets": {"to": 106000, "from": 104760}, "timestamps": {"to": "00:01:46,000", "from": "00:01:44,760"}}, {"text": "Были изменены", "offsets": {"to": 107520, "from": 106000}, "timestamps": {"to": "00:01:47,520", "from": "00:01:46,000"}}, {"text": "В данной транзакции", "offsets": {"to": 108880, "from": 107520}, "timestamps": {"to": "00:01:48,880", "from": "00:01:47,520"}}, {"text": "Они просто", "offsets": {"to": 109280, "from": 108880}, "timestamps": {"to": "00:01:49,280", "from": "00:01:48,880"}}, {"text": "Хранятся там же", "offsets": {"to": 110780, "from": 109280}, "timestamps": {"to": "00:01:50,780", "from": "00:01:49,280"}}, {"text": "Но со специальными", "offsets": {"to": 112300, "from": 110780}, "timestamps": {"to": "00:01:52,300", "from": "00:01:50,780"}}, {"text": "Грубо говоря", "offsets": {"to": 113260, "from": 112300}, "timestamps": {"to": "00:01:53,260", "from": "00:01:52,300"}}, {"text": "Ну, ключиками", "offsets": {"to": 113980, "from": 113260}, "timestamps": {"to": "00:01:53,980", "from": "00:01:53,260"}}, {"text": "Да", "offsets": {"to": 114140, "from": 113980}, "timestamps": {"to": "00:01:54,140", "from": "00:01:53,980"}}, {"text": "Какими-то флажками", "offsets": {"to": 115520, "from": 114140}, "timestamps": {"to": "00:01:55,520", "from": "00:01:54,140"}}, {"text": "Айдишниками", "offsets": {"to": 117160, "from": 115520}, "timestamps": {"to": "00:01:57,160", "from": "00:01:55,520"}}, {"text": "Транзакции", "offsets": {"to": 118060, "from": 117160}, "timestamps": {"to": "00:01:58,060", "from": "00:01:57,160"}}, {"text": "Которые понадлежат", "offsets": {"to": 119040, "from": 118060}, "timestamps": {"to": "00:01:59,040", "from": "00:01:58,060"}}, {"text": "Например, этой или этой", "offsets": {"to": 120120, "from": 119040}, "timestamps": {"to": "00:02:00,120", "from": "00:01:59,040"}}, {"text": "Это, видите", "offsets": {"to": 121400, "from": 120120}, "timestamps": {"to": "00:02:01,400", "from": "00:02:00,120"}}, {"text": "Тоже меняет", "offsets": {"to": 122080, "from": 121400}, "timestamps": {"to": "00:02:02,080", "from": "00:02:01,400"}}, {"text": "Какие-то данные", "offsets": {"to": 122920, "from": 122080}, "timestamps": {"to": "00:02:02,920", "from": "00:02:02,080"}}, {"text": "Вот", "offsets": {"to": 124420, "from": 122920}, "timestamps": {"to": "00:02:04,420", "from": "00:02:02,920"}}, {"text": "И", "offsets": {"to": 125540, "from": 124420}, "timestamps": {"to": "00:02:05,540", "from": "00:02:04,420"}}, {"text": "Первая и вторая транзакции", "offsets": {"to": 128080, "from": 125540}, "timestamps": {"to": "00:02:08,080", "from": "00:02:05,540"}}, {"text": "В данном случае", "offsets": {"to": 128860, "from": 128080}, "timestamps": {"to": "00:02:08,860", "from": "00:02:08,080"}}, {"text": "Они не могут", "offsets": {"to": 130820, "from": 128860}, "timestamps": {"to": "00:02:10,820", "from": "00:02:08,860"}}, {"text": "Видеть друг друга", "offsets": {"to": 131620, "from": 130820}, "timestamps": {"to": "00:02:11,620", "from": "00:02:10,820"}}, {"text": "То есть вот", "offsets": {"to": 133540, "from": 131620}, "timestamps": {"to": "00:02:13,540", "from": "00:02:11,620"}}, {"text": "Первая транзакция", "offsets": {"to": 134700, "from": 133540}, "timestamps": {"to": "00:02:14,700", "from": "00:02:13,540"}}, {"text": "Она пытается", "offsets": {"to": 135300, "from": 134700}, "timestamps": {"to": "00:02:15,300", "from": "00:02:14,700"}}, {"text": "Вот увидеть, да", "offsets": {"to": 135980, "from": 135300}, "timestamps": {"to": "00:02:15,980", "from": "00:02:15,300"}}, {"text": "Что, например", "offsets": {"to": 136880, "from": 135980}, "timestamps": {"to": "00:02:16,880", "from": "00:02:15,980"}}, {"text": "Вот этот вот", "offsets": {"to": 137480, "from": 136880}, "timestamps": {"to": "00:02:17,480", "from": "00:02:16,880"}}, {"text": "Был помененный", "offsets": {"to": 138180, "from": 137480}, "timestamps": {"to": "00:02:18,180", "from": "00:02:17,480"}}, {"text": "Она пытается", "offsets": {"to": 138800, "from": 138180}, "timestamps": {"to": "00:02:18,800", "from": "00:02:18,180"}}, {"text": "Вот сюда посмотреть", "offsets": {"to": 139700, "from": 138800}, "timestamps": {"to": "00:02:19,700", "from": "00:02:18,800"}}, {"text": "Но не может", "offsets": {"to": 140280, "from": 139700}, "timestamps": {"to": "00:02:20,280", "from": "00:02:19,700"}}, {"text": "У нее ошибка", "offsets": {"to": 141120, "from": 140280}, "timestamps": {"to": "00:02:21,120", "from": "00:02:20,280"}}, {"text": "Она никак не может увидеть", "offsets": {"to": 142360, "from": 141120}, "timestamps": {"to": "00:02:22,360", "from": "00:02:21,120"}}, {"text": "И эта транзакция", "offsets": {"to": 143900, "from": 142360}, "timestamps": {"to": "00:02:23,900", "from": "00:02:22,360"}}, {"text": "Например, меняет", "offsets": {"to": 144620, "from": 143900}, "timestamps": {"to": "00:02:24,620", "from": "00:02:23,900"}}, {"text": "Какие-то данные", "offsets": {"to": 145200, "from": 144620}, "timestamps": {"to": "00:02:25,200", "from": "00:02:24,620"}}, {"text": "Хочет посмотреть", "offsets": {"to": 146020, "from": 145200}, "timestamps": {"to": "00:02:26,020", "from": "00:02:25,200"}}, {"text": "А какие", "offsets": {"to": 147160, "from": 146020}, "timestamps": {"to": "00:02:27,160", "from": "00:02:26,020"}}, {"text": "То есть увидеть", "offsets": {"to": 148480, "from": 147160}, "timestamps": {"to": "00:02:28,480", "from": "00:02:27,160"}}, {"text": "Были ли они изменены", "offsets": {"to": 150140, "from": 148480}, "timestamps": {"to": "00:02:30,140", "from": "00:02:28,480"}}, {"text": "Вот здесь", "offsets": {"to": 150700, "from": 150140}, "timestamps": {"to": "00:02:30,700", "from": "00:02:30,140"}}, {"text": "Или не были", "offsets": {"to": 151540, "from": 150700}, "timestamps": {"to": "00:02:31,540", "from": "00:02:30,700"}}, {"text": "Но она не может", "offsets": {"to": 152860, "from": 151540}, "timestamps": {"to": "00:02:32,860", "from": "00:02:31,540"}}, {"text": "Этого сделать", "offsets": {"to": 153600, "from": 152860}, "timestamps": {"to": "00:02:33,600", "from": "00:02:32,860"}}, {"text": "Потому что", "offsets": {"to": 154400, "from": 153600}, "timestamps": {"to": "00:02:34,400", "from": "00:02:33,600"}}, {"text": "Есть специальный барьер", "offsets": {"to": 155520, "from": 154400}, "timestamps": {"to": "00:02:35,520", "from": "00:02:34,400"}}, {"text": "Он не разрешает", "offsets": {"to": 156480, "from": 155520}, "timestamps": {"to": "00:02:36,480", "from": "00:02:35,520"}}, {"text": "Этой транзакции", "offsets": {"to": 157280, "from": 156480}, "timestamps": {"to": "00:02:37,280", "from": "00:02:36,480"}}, {"text": "Видеть вообще ничего", "offsets": {"to": 158540, "from": 157280}, "timestamps": {"to": "00:02:38,540", "from": "00:02:37,280"}}, {"text": "Что здесь происходит", "offsets": {"to": 159720, "from": 158540}, "timestamps": {"to": "00:02:39,720", "from": "00:02:38,540"}}, {"text": "Она не видит", "offsets": {"to": 160440, "from": 159720}, "timestamps": {"to": "00:02:40,440", "from": "00:02:39,720"}}, {"text": "И эта транзакция", "offsets": {"to": 162600, "from": 160440}, "timestamps": {"to": "00:02:42,600", "from": "00:02:40,440"}}, {"text": "Она пытается", "offsets": {"to": 163320, "from": 162600}, "timestamps": {"to": "00:02:43,320", "from": "00:02:42,600"}}, {"text": "Сюда увидеть", "offsets": {"to": 164000, "from": 163320}, "timestamps": {"to": "00:02:44,000", "from": "00:02:43,320"}}, {"text": "И тоже не может", "offsets": {"to": 165220, "from": 164000}, "timestamps": {"to": "00:02:45,220", "from": "00:02:44,000"}}, {"text": "Вообще ничего увидеть", "offsets": {"to": 166500, "from": 165220}, "timestamps": {"to": "00:02:46,500", "from": "00:02:45,220"}}, {"text": "Это", "offsets": {"to": 167320, "from": 166500}, "timestamps": {"to": "00:02:47,320", "from": "00:02:46,500"}}, {"text": "По сути", "offsets": {"to": 168120, "from": 167320}, "timestamps": {"to": "00:02:48,120", "from": "00:02:47,320"}}, {"text": "Каждая транзакция", "offsets": {"to": 169000, "from": 168120}, "timestamps": {"to": "00:02:49,000", "from": "00:02:48,120"}}, {"text": "Будет являться", "offsets": {"to": 169840, "from": 169000}, "timestamps": {"to": "00:02:49,840", "from": "00:02:49,000"}}, {"text": "Отдельным потоком", "offsets": {"to": 171040, "from": 169840}, "timestamps": {"to": "00:02:51,040", "from": "00:02:49,840"}}, {"text": "Тредом", "offsets": {"to": 171740, "from": 171040}, "timestamps": {"to": "00:02:51,740", "from": "00:02:51,040"}}, {"text": "Который будет", "offsets": {"to": 172820, "from": 171740}, "timestamps": {"to": "00:02:52,820", "from": "00:02:51,740"}}, {"text": "Выполняться", "offsets": {"to": 173380, "from": 172820}, "timestamps": {"to": "00:02:53,380", "from": "00:02:52,820"}}, {"text": "Параллельно", "offsets": {"to": 174660, "from": 173660}, "timestamps": {"to": "00:02:54,660", "from": "00:02:53,660"}}, {"text": "Вот", "offsets": {"to": 175120, "from": 174660}, "timestamps": {"to": "00:02:55,120", "from": "00:02:54,660"}}, {"text": "И в котором", "offsets": {"to": 176820, "from": 175120}, "timestamps": {"to": "00:02:56,820", "from": "00:02:55,120"}}, {"text": "Будут ровно", "offsets": {"to": 177480, "from": 176820}, "timestamps": {"to": "00:02:57,480", "from": "00:02:56,820"}}, {"text": "Какие-то свои изменения", "offsets": {"to": 178560, "from": 177480}, "timestamps": {"to": "00:02:58,560", "from": "00:02:57,480"}}, {"text": "Как будто на стеке", "offsets": {"to": 179540, "from": 178560}, "timestamps": {"to": "00:02:59,540", "from": "00:02:58,560"}}, {"text": "Потока", "offsets": {"to": 180240, "from": 179540}, "timestamps": {"to": "00:03:00,240", "from": "00:02:59,540"}}, {"text": "Что-то там меняется", "offsets": {"to": 181300, "from": 180240}, "timestamps": {"to": "00:03:01,300", "from": "00:03:00,240"}}, {"text": "И никто этого не видит", "offsets": {"to": 182480, "from": 181300}, "timestamps": {"to": "00:03:02,480", "from": "00:03:01,300"}}, {"text": "Но есть и другие случаи", "offsets": {"to": 184180, "from": 182480}, "timestamps": {"to": "00:03:04,180", "from": "00:03:02,480"}}, {"text": "Естественно", "offsets": {"to": 184600, "from": 184180}, "timestamps": {"to": "00:03:04,600", "from": "00:03:04,180"}}, {"text": "Эту видимость", "offsets": {"to": 185160, "from": 184600}, "timestamps": {"to": "00:03:05,160", "from": "00:03:04,600"}}, {"text": "Мы можем контролировать", "offsets": {"to": 186180, "from": 185160}, "timestamps": {"to": "00:03:06,180", "from": "00:03:05,160"}}, {"text": "С помощью", "offsets": {"to": 186620, "from": 186180}, "timestamps": {"to": "00:03:06,620", "from": "00:03:06,180"}}, {"text": "Как раз", "offsets": {"to": 187120, "from": 186620}, "timestamps": {"to": "00:03:07,120", "from": "00:03:06,620"}}, {"text": "Вот этих уровней", "offsets": {"to": 188200, "from": 187120}, "timestamps": {"to": "00:03:08,200", "from": "00:03:07,120"}}, {"text": "Мы можем разрешать", "offsets": {"to": 189500, "from": 188200}, "timestamps": {"to": "00:03:09,500", "from": "00:03:08,200"}}, {"text": "Пройти через этот барьер", "offsets": {"to": 190860, "from": 189500}, "timestamps": {"to": "00:03:10,860", "from": "00:03:09,500"}}, {"text": "И увидеть", "offsets": {"to": 191620, "from": 190860}, "timestamps": {"to": "00:03:11,620", "from": "00:03:10,860"}}, {"text": "Или не пройти", "offsets": {"to": 193040, "from": 191620}, "timestamps": {"to": "00:03:13,040", "from": "00:03:11,620"}}, {"text": "И вот так", "offsets": {"to": 193680, "from": 193040}, "timestamps": {"to": "00:03:13,680", "from": "00:03:13,040"}}, {"text": "Запретить", "offsets": {"to": 194220, "from": 193680}, "timestamps": {"to": "00:03:14,220", "from": "00:03:13,680"}}, {"text": "Как это будет происходить", "offsets": {"to": 195880, "from": 194220}, "timestamps": {"to": "00:03:15,880", "from": "00:03:14,220"}}, {"text": "Как раз мы", "offsets": {"to": 196540, "from": 195880}, "timestamps": {"to": "00:03:16,540", "from": "00:03:15,880"}}, {"text": "Дальше разберем", "offsets": {"to": 197880, "from": 196540}, "timestamps": {"to": "00:03:17,880", "from": "00:03:16,540"}}, {"text": "Вот", "offsets": {"to": 200980, "from": 197880}, "timestamps": {"to": "00:03:20,980", "from": "00:03:17,880"}}]}',NULL,'Дальше Isolation Итак Изоляция говорит нам о том Что наши транзакции Должны каким-то образом быть изолированы Мы должны выбирать Что нам важно На каком уровне мы хотим изолировать Мы хотим максимальную Производительность, перформанс Или максимальную надежность Railability какой-нибудь Здесь я нарисовал еще один примерчик Вот То есть я тут написал Это base insurance Она контролирует, она убеждает Убеждается сама в том, что Как вообще транзакции Аффектят друг друга, влияют друг на друга Чтобы сохранить Баздах постоянно беспокоится О консистентности наших данных И мы помогаем в этом Вот, то есть на этой картинке Я схематически изобразил Что у нас есть какие-то данные в нашей базе данных И изоляцию я изобразил С помощью вот такого вот барьера Я их делал Видео по memory modules Memory consistent modules Очень похожая тема Есть какие-то данные Есть вот одна транзакция Есть вторая транзакция И они меняют как-то эти данные То есть первая транзакция Поменяла данные Вот эти, да Зелененькие Они стали изменены Оранжевые Эта транзакция будет иметь Свою собственную Прямо копию этих данных Postgres, например, может Копировать прямо вот эти данные В эту же таблицу Рядышком И помещать, что Этот рекорд Да Принадлежит вот этой транзакции Только ей Что он находится в ней Таким образом База данных Всегда понимает Какие зна